// Package session provides domain types and interfaces for managing AI coding sessions.
//
// A Session represents a unit of work with an AI agent (Claude Code, Cursor, etc.).
// Sessions can be nested - when a subagent runs, it creates a sub-session within
// the parent session.
//
// This package provides two levels of abstraction:
//
//  1. Sessions interface - High-level CRUD operations for full session objects,
//     combining session state with checkpoint data. This is the primary interface
//     for commands and the UI layer.
//
//  2. StateStore - Low-level primitive for managing session state files in
//     .git/entire-sessions/. This tracks active session state (base commit,
//     checkpoint count, etc.) but doesn't handle checkpoint content. Strategies
//     use this directly for performance-critical state management.
//
// See docs/architecture/sessions-and-checkpoints.md for the full domain model.
package session

import (
	"context"
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint"
)

// Session represents a unit of work with an AI coding agent.
// Sessions can be nested when subagents are used.
type Session struct {
	// ID is the unique session identifier
	ID string

	// FirstPrompt is the raw first user prompt (immutable)
	FirstPrompt string

	// Description is a human-readable summary (derived or editable)
	Description string

	// StartTime is when the session was started
	StartTime time.Time

	// AgentType identifies the AI agent (e.g., "Claude Code", "Cursor")
	AgentType agent.AgentType

	// AgentSessionID is the agent's internal session identifier
	AgentSessionID string

	// Checkpoints contains save points within this session
	Checkpoints []checkpoint.Checkpoint

	// SubSessions contains nested sessions from subagent work
	SubSessions []Session

	// ParentID is the parent session ID (empty for top-level sessions)
	ParentID string

	// ToolUseID is the tool invocation that spawned this sub-session
	// (empty for top-level sessions)
	ToolUseID string
}

// IsSubSession returns true if this session is a sub-session (has a parent).
func (s *Session) IsSubSession() bool {
	return s.ParentID != ""
}

// Sessions provides operations for managing sessions.
type Sessions interface {
	// Create creates a new session with the given options.
	Create(ctx context.Context, opts CreateSessionOptions) (*Session, error)

	// Get retrieves a session by ID.
	Get(ctx context.Context, sessionID string) (*Session, error)

	// List returns all top-level sessions (excludes sub-sessions).
	List(ctx context.Context) ([]Session, error)
}

// CreateSessionOptions contains parameters for creating a new session.
type CreateSessionOptions struct {
	// FirstPrompt is the initial user prompt
	FirstPrompt string

	// AgentType identifies the AI agent (e.g., "Claude Code", "Cursor")
	AgentType agent.AgentType

	// AgentSessionID is the agent's internal session identifier
	AgentSessionID string

	// ParentID is the parent session ID for sub-sessions (empty for top-level)
	ParentID string

	// ToolUseID is the tool invocation that spawned this sub-session
	// (empty for top-level sessions)
	ToolUseID string
}

package session

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint/id"
	"entire.io/cli/cmd/entire/cli/jsonutil"
	"entire.io/cli/cmd/entire/cli/logging"
	"entire.io/cli/cmd/entire/cli/sessionid"
	"entire.io/cli/cmd/entire/cli/validation"
)

const (
	// sessionStateDirName is the directory name for session state files within git common dir.
	sessionStateDirName = "entire-sessions"
)

// State represents the state of an active session.
// This is stored in .git/entire-sessions/<session-id>.json
type State struct {
	// SessionID is the unique session identifier
	SessionID string `json:"session_id"`

	// BaseCommit is the HEAD commit when the session started
	BaseCommit string `json:"base_commit"`

	// WorktreePath is the absolute path to the worktree root
	WorktreePath string `json:"worktree_path,omitempty"`

	// StartedAt is when the session was started
	StartedAt time.Time `json:"started_at"`

	// CheckpointCount is the number of checkpoints created in this session
	CheckpointCount int `json:"checkpoint_count"`

	// CondensedTranscriptLines tracks lines already included in previous condensation
	CondensedTranscriptLines int `json:"condensed_transcript_lines,omitempty"`

	// UntrackedFilesAtStart tracks files that existed at session start (to preserve during rewind)
	UntrackedFilesAtStart []string `json:"untracked_files_at_start,omitempty"`

	// FilesTouched tracks files modified/created/deleted during this session
	FilesTouched []string `json:"files_touched,omitempty"`

	// ConcurrentWarningShown is true if user was warned about concurrent sessions
	ConcurrentWarningShown bool `json:"concurrent_warning_shown,omitempty"`

	// LastCheckpointID is the checkpoint ID from last condensation, reused for subsequent commits without new content
	LastCheckpointID id.CheckpointID `json:"last_checkpoint_id,omitempty"`

	// AgentType identifies the agent that created this session (e.g., "Claude Code", "Gemini CLI", "Cursor")
	AgentType agent.AgentType `json:"agent_type,omitempty"`

	// Token usage tracking (accumulated across all checkpoints in this session)
	TokenUsage *agent.TokenUsage `json:"token_usage,omitempty"`

	// Transcript position when session started (for multi-session checkpoints)
	TranscriptLinesAtStart      int    `json:"transcript_lines_at_start,omitempty"`
	TranscriptIdentifierAtStart string `json:"transcript_identifier_at_start,omitempty"`

	// TranscriptPath is the path to the live transcript file (for mid-session commit detection)
	TranscriptPath string `json:"transcript_path,omitempty"`

	// PromptAttributions tracks user and agent line changes at each prompt start.
	// This enables accurate attribution by capturing user edits between checkpoints.
	PromptAttributions []PromptAttribution `json:"prompt_attributions,omitempty"`

	// PendingPromptAttribution holds attribution calculated at prompt start (before agent runs).
	// This is moved to PromptAttributions when SaveChanges is called.
	PendingPromptAttribution *PromptAttribution `json:"pending_prompt_attribution,omitempty"`
}

// PromptAttribution captures line-level attribution data at the start of each prompt.
// By recording what changed since the last checkpoint BEFORE the agent works,
// we can accurately separate user edits from agent contributions.
type PromptAttribution struct {
	// CheckpointNumber is which checkpoint this was recorded before (1-indexed)
	CheckpointNumber int `json:"checkpoint_number"`

	// UserLinesAdded is lines added by user since the last checkpoint
	UserLinesAdded int `json:"user_lines_added"`

	// UserLinesRemoved is lines removed by user since the last checkpoint
	UserLinesRemoved int `json:"user_lines_removed"`

	// AgentLinesAdded is total agent lines added so far (base → last checkpoint).
	// Always 0 for checkpoint 1 since there's no previous checkpoint to measure against.
	AgentLinesAdded int `json:"agent_lines_added"`

	// AgentLinesRemoved is total agent lines removed so far (base → last checkpoint).
	// Always 0 for checkpoint 1 since there's no previous checkpoint to measure against.
	AgentLinesRemoved int `json:"agent_lines_removed"`

	// UserAddedPerFile tracks per-file user additions for accurate modification tracking.
	// This enables distinguishing user self-modifications from agent modifications.
	// See docs/architecture/attribution.md for details.
	UserAddedPerFile map[string]int `json:"user_added_per_file,omitempty"`
}

// StateStore provides low-level operations for managing session state files.
//
// StateStore is a primitive for session state persistence. It is NOT the same as
// the Sessions interface - it only handles state files in .git/entire-sessions/,
// not the full session data which includes checkpoint content.
//
// Use StateStore directly in strategies for performance-critical state operations.
// Use the Sessions interface (when implemented) for high-level session management.
type StateStore struct {
	// stateDir is the directory where session state files are stored
	stateDir string
}

// NewStateStore creates a new state store.
// Uses the git common dir to store session state (shared across worktrees).
func NewStateStore() (*StateStore, error) {
	commonDir, err := getGitCommonDir()
	if err != nil {
		return nil, fmt.Errorf("failed to get git common dir: %w", err)
	}
	return &StateStore{
		stateDir: filepath.Join(commonDir, sessionStateDirName),
	}, nil
}

// NewStateStoreWithDir creates a new state store with a custom directory.
// This is useful for testing.
func NewStateStoreWithDir(stateDir string) *StateStore {
	return &StateStore{stateDir: stateDir}
}

// Load loads the session state for the given session ID.
// Returns (nil, nil) when session file doesn't exist (not an error condition).
func (s *StateStore) Load(ctx context.Context, sessionID string) (*State, error) {
	_ = ctx // Reserved for future use

	// Validate session ID to prevent path traversal
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return nil, fmt.Errorf("invalid session ID: %w", err)
	}

	stateFile := s.stateFilePath(sessionID)

	data, err := os.ReadFile(stateFile) //nolint:gosec // stateFile is derived from sessionID
	if os.IsNotExist(err) {
		return nil, nil //nolint:nilnil // nil,nil indicates session not found (expected case)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read session state: %w", err)
	}

	var state State
	if err := json.Unmarshal(data, &state); err != nil {
		return nil, fmt.Errorf("failed to unmarshal session state: %w", err)
	}
	return &state, nil
}

// Save saves the session state atomically.
func (s *StateStore) Save(ctx context.Context, state *State) error {
	_ = ctx // Reserved for future use

	// Validate session ID to prevent path traversal
	if err := validation.ValidateSessionID(state.SessionID); err != nil {
		return fmt.Errorf("invalid session ID: %w", err)
	}

	if err := os.MkdirAll(s.stateDir, 0o750); err != nil {
		return fmt.Errorf("failed to create session state directory: %w", err)
	}

	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal session state: %w", err)
	}

	stateFile := s.stateFilePath(state.SessionID)

	// Atomic write: write to temp file, then rename
	tmpFile := stateFile + ".tmp"
	if err := os.WriteFile(tmpFile, data, 0o600); err != nil {
		return fmt.Errorf("failed to write session state: %w", err)
	}
	if err := os.Rename(tmpFile, stateFile); err != nil {
		return fmt.Errorf("failed to rename session state file: %w", err)
	}
	return nil
}

// Clear removes the session state file for the given session ID.
func (s *StateStore) Clear(ctx context.Context, sessionID string) error {
	_ = ctx // Reserved for future use

	// Validate session ID to prevent path traversal
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return fmt.Errorf("invalid session ID: %w", err)
	}

	stateFile := s.stateFilePath(sessionID)

	if err := os.Remove(stateFile); err != nil {
		if os.IsNotExist(err) {
			return nil // Already gone, not an error
		}
		return fmt.Errorf("failed to remove session state file: %w", err)
	}
	return nil
}

// RemoveAll removes the entire session state directory.
// This is used during uninstall to completely remove all session state.
func (s *StateStore) RemoveAll() error {
	if err := os.RemoveAll(s.stateDir); err != nil {
		return fmt.Errorf("failed to remove session state directory: %w", err)
	}
	return nil
}

// List returns all session states.
func (s *StateStore) List(ctx context.Context) ([]*State, error) {
	_ = ctx // Reserved for future use

	entries, err := os.ReadDir(s.stateDir)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read session state directory: %w", err)
	}

	var states []*State
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
			continue
		}
		if strings.HasSuffix(entry.Name(), ".tmp") {
			continue // Skip temp files
		}

		sessionID := strings.TrimSuffix(entry.Name(), ".json")
		state, err := s.Load(ctx, sessionID)
		if err != nil {
			continue // Skip corrupted state files
		}
		if state == nil {
			continue
		}

		states = append(states, state)
	}
	return states, nil
}

// FindByBaseCommit finds all sessions based on the given commit hash.
func (s *StateStore) FindByBaseCommit(ctx context.Context, baseCommit string) ([]*State, error) {
	allStates, err := s.List(ctx)
	if err != nil {
		return nil, err
	}

	var matching []*State
	for _, state := range allStates {
		if state.BaseCommit == baseCommit {
			matching = append(matching, state)
		}
	}
	return matching, nil
}

// FindByWorktree finds all sessions for the given worktree path.
func (s *StateStore) FindByWorktree(ctx context.Context, worktreePath string) ([]*State, error) {
	allStates, err := s.List(ctx)
	if err != nil {
		return nil, err
	}

	var matching []*State
	for _, state := range allStates {
		if state.WorktreePath == worktreePath {
			matching = append(matching, state)
		}
	}
	return matching, nil
}

// stateFilePath returns the path to a session state file.
func (s *StateStore) stateFilePath(sessionID string) string {
	return filepath.Join(s.stateDir, sessionID+".json")
}

// getGitCommonDir returns the path to the shared git directory.
// In a regular checkout, this is .git/
// In a worktree, this is the main repo's .git/ (not .git/worktrees/<name>/)
func getGitCommonDir() (string, error) {
	ctx := context.Background()
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
	cmd.Dir = "."
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get git common dir: %w", err)
	}

	commonDir := strings.TrimSpace(string(output))

	// git rev-parse --git-common-dir returns relative paths from the working directory,
	// so we need to make it absolute if it isn't already
	if !filepath.IsAbs(commonDir) {
		commonDir = filepath.Join(".", commonDir)
	}

	return filepath.Clean(commonDir), nil
}

// GetWorktreePath returns the absolute path to the current worktree root.
func GetWorktreePath() (string, error) {
	ctx := context.Background()
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get worktree path: %w", err)
	}
	return strings.TrimSpace(string(output)), nil
}

// GetOrCreateEntireSessionID returns a stable session ID for the given agent session ID.
// If a session state already exists with this ID, returns that session ID
// (preserving the original date prefix). Otherwise creates a new ID with today's date.
//
// When multiple state files exist for the same ID (due to the midnight-crossing bug),
// this function picks the most recent by date and cleans up older duplicates.
//
// This function never returns an error - it always falls back to generating a new ID
// if any issues occur (e.g., corrupt git repo, permission problems, invalid ID).
//
// Note: This function is not thread-safe. Concurrent calls with the same ID may
// race on file cleanup. In practice this is not an issue since agent hooks are
// called sequentially within a session.
func GetOrCreateEntireSessionID(agentSessionID string) string {
	// Validate ID format to prevent path traversal attacks
	if err := validation.ValidateAgentSessionID(agentSessionID); err != nil {
		logging.Warn(context.Background(), "invalid agent session ID",
			slog.String("input", agentSessionID),
			slog.Any("error", err))
		// Invalid ID - return it anyway (will fail downstream with clearer error)
		// Don't generate random ID as that breaks session continuity
		return sessionid.EntireSessionID(agentSessionID)
	}

	commonDir, err := getGitCommonDir()
	if err != nil {
		// Can't get common dir (corrupt git repo?) - fall back to new ID
		return sessionid.EntireSessionID(agentSessionID)
	}

	stateDir := filepath.Join(commonDir, sessionStateDirName)
	entries, err := os.ReadDir(stateDir)
	if err != nil {
		// State dir doesn't exist or can't read it - fall back to new ID
		return sessionid.EntireSessionID(agentSessionID)
	}

	// Collect all matching session IDs
	var matches []string
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
			continue
		}

		existingSessionID := strings.TrimSuffix(entry.Name(), ".json")
		existingUUID := sessionid.ModelSessionID(existingSessionID)

		if existingUUID == agentSessionID {
			matches = append(matches, existingSessionID)
		}
	}

	if len(matches) == 0 {
		// No existing session found - create new ID with today's date
		return sessionid.EntireSessionID(agentSessionID)
	}

	// Pick most recent (YYYY-MM-DD sorts correctly lexicographically)
	sort.Strings(matches)
	mostRecent := matches[len(matches)-1]

	// Best-effort cleanup of old duplicates (ignore errors)
	for _, oldID := range matches[:len(matches)-1] {
		oldFile := filepath.Join(stateDir, oldID+".json")
		_ = os.Remove(oldFile)
	}

	return mostRecent
}

package strategy

import (
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint/id"
)

const (
	// sessionStateDirName is the directory name for session state files within git common dir.
	sessionStateDirName = "entire-sessions"

	// logsOnlyScanLimit is the maximum number of commits to scan for logs-only points.
	logsOnlyScanLimit = 50
)

// SessionState represents the state of an active session.
type SessionState struct {
	SessionID                string          `json:"session_id"`
	BaseCommit               string          `json:"base_commit"`
	WorktreePath             string          `json:"worktree_path,omitempty"` // Absolute path to the worktree root
	StartedAt                time.Time       `json:"started_at"`
	CheckpointCount          int             `json:"checkpoint_count"`
	CondensedTranscriptLines int             `json:"condensed_transcript_lines,omitempty"` // Lines already included in previous condensation
	UntrackedFilesAtStart    []string        `json:"untracked_files_at_start,omitempty"`   // Files that existed at session start (to preserve during rewind)
	FilesTouched             []string        `json:"files_touched,omitempty"`              // Files modified/created/deleted during this session
	ConcurrentWarningShown   bool            `json:"concurrent_warning_shown,omitempty"`   // True if user was warned about concurrent sessions
	LastCheckpointID         id.CheckpointID `json:"last_checkpoint_id,omitempty"`         // Checkpoint ID from last condensation, reused for subsequent commits without new content
	AgentType                agent.AgentType `json:"agent_type,omitempty"`                 // Agent type identifier (e.g., "Claude Code", "Cursor")
	TranscriptPath           string          `json:"transcript_path,omitempty"`            // Path to the live transcript file (for mid-session commit detection)

	// Token usage tracking (accumulated across all checkpoints in this session)
	TokenUsage *agent.TokenUsage `json:"token_usage,omitempty"`

	// Transcript position when session started (for multi-session checkpoints on entire/sessions)
	TranscriptLinesAtStart      int    `json:"transcript_lines_at_start,omitempty"`
	TranscriptIdentifierAtStart string `json:"transcript_identifier_at_start,omitempty"`

	// PromptAttributions tracks user and agent line changes at each prompt start.
	PromptAttributions []PromptAttribution `json:"prompt_attributions,omitempty"`

	// PendingPromptAttribution holds attribution calculated at prompt start (before agent runs).
	// This is moved to PromptAttributions when SaveChanges is called.
	PendingPromptAttribution *PromptAttribution `json:"pending_prompt_attribution,omitempty"`
}

// PromptAttribution captures line-level attribution data at the start of each prompt,
// calculated BEFORE the agent runs. This allows us to separate user edits (made between
// prompts) from agent edits (made during prompt execution).
//
// Fields:
//   - CheckpointNumber: Which checkpoint this attribution is for (1-indexed)
//   - UserLinesAdded/Removed: User edits since the last checkpoint (lastCheckpoint → worktree)
//   - AgentLinesAdded/Removed: Cumulative agent work so far (base → lastCheckpoint)
//   - UserAddedPerFile: Per-file breakdown of user additions (for accurate modification tracking)
//
// Note: For checkpoint 1, AgentLinesAdded/Removed are always 0 because there is no previous
// checkpoint to compare against. This doesn't mean the agent hasn't done work yet - it means
// we can't measure cumulative agent work until after the first checkpoint is created.
// These fields become meaningful starting from checkpoint 2.
//
// UserAddedPerFile enables accurate tracking of user self-modifications. When a user modifies
// their own previously-added lines (not agent lines), we shouldn't subtract from the agent's
// contribution. See docs/architecture/attribution.md for details.
type PromptAttribution struct {
	CheckpointNumber            int            `json:"checkpoint_number"`
	UserLinesAdded              int            `json:"user_lines_added"`
	UserLinesRemoved            int            `json:"user_lines_removed"`
	AgentLinesAdded             int            `json:"agent_lines_added"`             // Always 0 for checkpoint 1 (no previous checkpoint)
	AgentLinesRemoved           int            `json:"agent_lines_removed"`           // Always 0 for checkpoint 1 (no previous checkpoint)
	UserAddedPerFile            map[string]int `json:"user_added_per_file,omitempty"` // Per-file user additions for modification tracking
	TranscriptLinesAtStart      int            `json:"transcript_lines_at_start,omitempty"`
	TranscriptIdentifierAtStart string         `json:"transcript_identifier_at_start,omitempty"`
}

// CheckpointInfo represents checkpoint metadata stored on the sessions branch.
// Metadata is stored at sharded path: <checkpoint_id[:2]>/<checkpoint_id[2:]>/
type CheckpointInfo struct {
	CheckpointID     id.CheckpointID `json:"checkpoint_id"` // 12-hex-char from Entire-Checkpoint trailer, used as directory path
	SessionID        string          `json:"session_id"`
	CreatedAt        time.Time       `json:"created_at"`
	CheckpointsCount int             `json:"checkpoints_count"`
	FilesTouched     []string        `json:"files_touched"`
	Agent            agent.AgentType `json:"agent,omitempty"` // Human-readable agent name (e.g., "Claude Code")
	IsTask           bool            `json:"is_task,omitempty"`
	ToolUseID        string          `json:"tool_use_id,omitempty"`
	SessionCount     int             `json:"session_count,omitempty"` // Number of sessions (1 if omitted)
	SessionIDs       []string        `json:"session_ids,omitempty"`   // All session IDs in this checkpoint
}

// CondenseResult contains the result of a session condensation operation.
type CondenseResult struct {
	CheckpointID         id.CheckpointID // 12-hex-char from Entire-Checkpoint trailer, used as directory path
	SessionID            string
	CheckpointsCount     int
	FilesTouched         []string
	TotalTranscriptLines int // Total lines in transcript after this condensation
}

// ExtractedSessionData contains data extracted from a shadow branch.
type ExtractedSessionData struct {
	Transcript          []byte   // Full transcript content for the session
	FullTranscriptLines int      // Total line count in full transcript
	Prompts             []string // All user prompts from this portion
	Context             []byte   // Generated context.md content
	FilesTouched        []string
	TokenUsage          *agent.TokenUsage // Token usage calculated from transcript (since TranscriptLinesAtStart)
}

package strategy

import (
	"slices"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/checkpoint"
	"github.com/go-git/go-git/v5/plumbing/object"
	"github.com/sergi/go-diff/diffmatchpatch"
)

// getAllChangedFilesBetweenTrees returns a list of all files that differ between two trees.
// This includes files that were added, modified, or deleted in either tree.
// Uses git blob hashes for efficient comparison without reading file contents.
func getAllChangedFilesBetweenTrees(tree1, tree2 *object.Tree) []string {
	if tree1 == nil && tree2 == nil {
		return nil
	}

	// Build hash maps for each tree - O(n) iteration, no content reading
	tree1Hashes := make(map[string]string)
	tree2Hashes := make(map[string]string)

	if tree1 != nil {
		//nolint:errcheck // Errors ignored - just collecting file hashes for diff comparison
		_ = tree1.Files().ForEach(func(f *object.File) error {
			tree1Hashes[f.Name] = f.Hash.String()
			return nil
		})
	}

	if tree2 != nil {
		//nolint:errcheck // Errors ignored - just collecting file hashes for diff comparison
		_ = tree2.Files().ForEach(func(f *object.File) error {
			tree2Hashes[f.Name] = f.Hash.String()
			return nil
		})
	}

	// Find changed files by comparing hashes (much faster than content comparison)
	var changed []string

	// Check files in tree1 - either modified or deleted in tree2
	for path, hash1 := range tree1Hashes {
		if hash2, exists := tree2Hashes[path]; !exists || hash1 != hash2 {
			changed = append(changed, path)
		}
	}

	// Check files only in tree2 (added files)
	for path := range tree2Hashes {
		if _, exists := tree1Hashes[path]; !exists {
			changed = append(changed, path)
		}
	}

	return changed
}

// getFileContent retrieves the content of a file from a tree.
// Returns empty string if the file doesn't exist, can't be read, or is a binary file.
//
// Binary files are silently excluded from attribution calculations because line-based
// diffing doesn't apply to binary content. This means binary files (images, compiled
// binaries, etc.) won't appear in attribution metrics even if they were added or modified.
// This is intentional - attribution measures code contributions via line counting,
// which only makes sense for text files.
//
// Uses go-git's IsBinary() which implements git's binary detection algorithm.
//
// TODO: Consider tracking binary file counts separately (e.g., BinaryFilesChanged field)
// to provide visibility into non-text file modifications.
func getFileContent(tree *object.Tree, path string) string {
	if tree == nil {
		return ""
	}

	file, err := tree.File(path)
	if err != nil {
		return ""
	}

	// Use git's binary detection algorithm
	isBinary, err := file.IsBinary()
	if err != nil || isBinary {
		return ""
	}

	content, err := file.Contents()
	if err != nil {
		return ""
	}

	return content
}

// diffLines compares two strings and returns line-level diff stats.
// Returns (unchanged, added, removed) line counts.
func diffLines(checkpointContent, committedContent string) (unchanged, added, removed int) {
	// Handle edge cases
	if checkpointContent == committedContent {
		return countLinesStr(committedContent), 0, 0
	}
	if checkpointContent == "" {
		return 0, countLinesStr(committedContent), 0
	}
	if committedContent == "" {
		return 0, 0, countLinesStr(checkpointContent)
	}

	dmp := diffmatchpatch.New()

	// Convert to line-based diff using DiffLinesToChars/DiffCharsToLines pattern
	text1, text2, lineArray := dmp.DiffLinesToChars(checkpointContent, committedContent)
	diffs := dmp.DiffMain(text1, text2, false)
	diffs = dmp.DiffCharsToLines(diffs, lineArray)

	for _, d := range diffs {
		lines := countLinesStr(d.Text)
		switch d.Type {
		case diffmatchpatch.DiffEqual:
			unchanged += lines
		case diffmatchpatch.DiffInsert:
			added += lines
		case diffmatchpatch.DiffDelete:
			removed += lines
		}
	}

	return unchanged, added, removed
}

// countLinesStr returns the number of lines in a string.
// An empty string has 0 lines. A string without newlines has 1 line.
// This is used for both file content and diff text segments.
func countLinesStr(content string) int {
	if content == "" {
		return 0
	}
	lines := strings.Count(content, "\n")
	// If content doesn't end with newline, add 1 for the last line
	if !strings.HasSuffix(content, "\n") {
		lines++
	}
	return lines
}

// CalculateAttributionWithAccumulated computes final attribution using accumulated prompt data.
// This provides more accurate attribution than tree-only comparison because it captures
// user edits that happened between checkpoints (which would otherwise be mixed into the
// checkpoint snapshots).
//
// The calculation:
// 1. Sum user edits from PromptAttributions (captured at each prompt start)
// 2. Add user edits after the final checkpoint (shadow → head diff)
// 3. Calculate agent lines from base → shadow
// 4. Estimate user self-modifications vs agent modifications using per-file tracking
// 5. Compute percentages
//
// Note: Binary files (detected by null bytes) are silently excluded from attribution
// calculations since line-based diffing only applies to text files.
//
// See docs/architecture/attribution.md for details on the per-file tracking approach.
func CalculateAttributionWithAccumulated(
	baseTree *object.Tree,
	shadowTree *object.Tree,
	headTree *object.Tree,
	filesTouched []string,
	promptAttributions []PromptAttribution,
) *checkpoint.InitialAttribution {
	if len(filesTouched) == 0 {
		return nil
	}

	// Sum accumulated user lines from prompt attributions
	// Also aggregate per-file user additions for accurate modification tracking
	var accumulatedUserAdded, accumulatedUserRemoved int
	accumulatedUserAddedPerFile := make(map[string]int)
	for _, pa := range promptAttributions {
		accumulatedUserAdded += pa.UserLinesAdded
		accumulatedUserRemoved += pa.UserLinesRemoved
		// Merge per-file data from all prompt attributions
		for filePath, added := range pa.UserAddedPerFile {
			accumulatedUserAddedPerFile[filePath] += added
		}
	}

	// Calculate attribution for agent-touched files
	// IMPORTANT: shadowTree is a snapshot of the worktree at checkpoint time,
	// which includes both agent work AND accumulated user edits (to agent-touched files).
	// So base→shadow diff = (agent work + accumulated user work to these files).
	var totalAgentAndUserWork int
	var postCheckpointUserAdded, postCheckpointUserRemoved int
	postCheckpointUserRemovedPerFile := make(map[string]int)

	for _, filePath := range filesTouched {
		baseContent := getFileContent(baseTree, filePath)
		shadowContent := getFileContent(shadowTree, filePath)
		headContent := getFileContent(headTree, filePath)

		// Total work in shadow: base → shadow (agent + accumulated user work for this file)
		_, workAdded, _ := diffLines(baseContent, shadowContent)
		totalAgentAndUserWork += workAdded

		// Post-checkpoint user edits: shadow → head (only post-checkpoint edits for this file)
		_, postUserAdded, postUserRemoved := diffLines(shadowContent, headContent)
		postCheckpointUserAdded += postUserAdded
		postCheckpointUserRemoved += postUserRemoved

		// Track per-file removals for self-modification estimation
		if postUserRemoved > 0 {
			postCheckpointUserRemovedPerFile[filePath] = postUserRemoved
		}
	}

	// Calculate total user edits to non-agent files (files not in filesTouched)
	// These files are not in the shadow tree, so base→head captures ALL their user edits
	nonAgentFiles := getAllChangedFilesBetweenTrees(baseTree, headTree)
	var allUserEditsToNonAgentFiles int
	for _, filePath := range nonAgentFiles {
		if slices.Contains(filesTouched, filePath) {
			continue // Skip agent-touched files
		}

		baseContent := getFileContent(baseTree, filePath)
		headContent := getFileContent(headTree, filePath)
		_, userAdded, _ := diffLines(baseContent, headContent)
		allUserEditsToNonAgentFiles += userAdded
	}

	// Separate accumulated edits by file type using per-file tracking data.
	// This is precise because accumulatedUserAddedPerFile tells us exactly which files
	// the user edited between checkpoints.
	var accumulatedToAgentFiles, accumulatedToNonAgentFiles int
	for filePath, added := range accumulatedUserAddedPerFile {
		if slices.Contains(filesTouched, filePath) {
			accumulatedToAgentFiles += added
		} else {
			accumulatedToNonAgentFiles += added
		}
	}

	// Agent work = (base→shadow for agent files) - (accumulated user edits to agent files only)
	totalAgentAdded := max(0, totalAgentAndUserWork-accumulatedToAgentFiles)

	// Post-checkpoint edits to non-agent files = total edits - accumulated portion (never negative)
	postToNonAgentFiles := max(0, allUserEditsToNonAgentFiles-accumulatedToNonAgentFiles)

	// Total user contribution = accumulated (all files) + post-checkpoint (agent files) + post-checkpoint (non-agent files)
	totalUserAdded := accumulatedUserAdded + postCheckpointUserAdded + postToNonAgentFiles
	totalUserRemoved := accumulatedUserRemoved + postCheckpointUserRemoved

	// Estimate modified lines (user changed existing lines)
	// Lines that were both added and removed are treated as modifications.
	totalHumanModified := min(totalUserAdded, totalUserRemoved)

	// Estimate user self-modifications using per-file tracking (see docs/architecture/attribution.md)
	// When a user removes lines from a file, assume they're removing their own lines first (LIFO).
	// Only after exhausting their own additions should we count removals as targeting agent lines.
	userSelfModified := estimateUserSelfModifications(accumulatedUserAddedPerFile, postCheckpointUserRemovedPerFile)

	// humanModifiedAgent = modifications that targeted agent lines (not user's own lines)
	humanModifiedAgent := max(0, totalHumanModified-userSelfModified)

	// Remaining modifications are user self-modifications (user edited their own code)
	// These should NOT be subtracted from agent lines
	pureUserAdded := totalUserAdded - totalHumanModified
	pureUserRemoved := totalUserRemoved - totalHumanModified

	// Total net additions = agent additions + pure user additions - pure user removals
	// This reconstructs the base → head diff from our tracked changes.
	// Note: This measures "net new lines added to the codebase" not total file size.
	// pureUserRemoved represents agent lines that the user deleted, so we subtract them.
	totalCommitted := totalAgentAdded + pureUserAdded - pureUserRemoved
	if totalCommitted <= 0 {
		// Fallback for delete-only commits or when removals exceed additions
		// Note: If both are 0 (deletion-only commit where agent added nothing),
		// totalCommitted will be 0 and percentage will be 0. This is expected -
		// the attribution percentage is only meaningful for commits that add code.
		totalCommitted = max(0, totalAgentAdded)
	}

	// Calculate agent lines actually in the commit (excluding removed and modified)
	// Agent added lines, but user removed some and modified others.
	// Only subtract modifications that targeted AGENT lines (humanModifiedAgent),
	// not user self-modifications.
	// Clamp to 0 to handle cases where user removed/modified more than agent added.
	agentLinesInCommit := max(0, totalAgentAdded-pureUserRemoved-humanModifiedAgent)

	// Calculate percentage
	var agentPercentage float64
	if totalCommitted > 0 {
		agentPercentage = float64(agentLinesInCommit) / float64(totalCommitted) * 100
	}

	return &checkpoint.InitialAttribution{
		CalculatedAt:    time.Now().UTC(),
		AgentLines:      agentLinesInCommit,
		HumanAdded:      pureUserAdded,
		HumanModified:   totalHumanModified, // Total modifications (for reporting)
		HumanRemoved:    pureUserRemoved,
		TotalCommitted:  totalCommitted,
		AgentPercentage: agentPercentage,
	}
}

// estimateUserSelfModifications estimates how many removed lines were the user's own additions.
// Uses LIFO assumption: when a user removes lines from a file, they likely remove their own
// recent additions before touching agent lines.
//
// See docs/architecture/attribution.md for the rationale behind this heuristic.
func estimateUserSelfModifications(
	accumulatedUserAddedPerFile map[string]int,
	postCheckpointUserRemovedPerFile map[string]int,
) int {
	var selfModified int
	for filePath, removed := range postCheckpointUserRemovedPerFile {
		userAddedToFile := accumulatedUserAddedPerFile[filePath]
		// User can only self-modify up to what they previously added
		selfModified += min(removed, userAddedToFile)
	}
	return selfModified
}

// CalculatePromptAttribution computes line-level attribution at the start of a prompt.
// This captures user edits since the last checkpoint BEFORE the agent makes changes.
//
// Parameters:
//   - baseTree: the tree at session start (the base commit)
//   - lastCheckpointTree: the tree from the previous checkpoint (nil if first checkpoint)
//   - worktreeFiles: map of file path → current worktree content for files that changed
//   - checkpointNumber: which checkpoint we're about to create (1-indexed)
//
// Returns the attribution data to store in session state. For checkpoint 1 (when
// lastCheckpointTree is nil), AgentLinesAdded/Removed will be 0 since there's no
// previous checkpoint to measure cumulative agent work against.
//
// Note: Binary files (detected by null bytes) in reference trees are silently excluded
// from attribution calculations since line-based diffing only applies to text files.
func CalculatePromptAttribution(
	baseTree *object.Tree,
	lastCheckpointTree *object.Tree,
	worktreeFiles map[string]string,
	checkpointNumber int,
) PromptAttribution {
	result := PromptAttribution{
		CheckpointNumber: checkpointNumber,
		UserAddedPerFile: make(map[string]int),
	}

	if len(worktreeFiles) == 0 {
		return result
	}

	// Determine reference tree for user changes (last checkpoint or base)
	referenceTree := lastCheckpointTree
	if referenceTree == nil {
		referenceTree = baseTree
	}

	for filePath, worktreeContent := range worktreeFiles {
		referenceContent := getFileContent(referenceTree, filePath)
		baseContent := getFileContent(baseTree, filePath)

		// User changes: diff(reference, worktree)
		// These are changes since the last checkpoint that the agent didn't make
		_, userAdded, userRemoved := diffLines(referenceContent, worktreeContent)
		result.UserLinesAdded += userAdded
		result.UserLinesRemoved += userRemoved

		// Track per-file user additions for accurate modification tracking.
		// This enables distinguishing user self-modifications from agent modifications.
		if userAdded > 0 {
			result.UserAddedPerFile[filePath] = userAdded
		}

		// Agent lines so far: diff(base, lastCheckpoint)
		// Only calculate if we have a previous checkpoint
		if lastCheckpointTree != nil {
			checkpointContent := getFileContent(lastCheckpointTree, filePath)
			_, agentAdded, agentRemoved := diffLines(baseContent, checkpointContent)
			result.AgentLinesAdded += agentAdded
			result.AgentLinesRemoved += agentRemoved
		}
	}

	return result
}

