// InitializeSession creates session state for a new session.
// This is called during UserPromptSubmit hook to set up tracking for the session.
// For auto-commit strategy, this creates a SessionState file in .git/entire-sessions/
// to track CondensedTranscriptLines (transcript offset) across checkpoints.
// agentType is the human-readable name of the agent (e.g., "Claude Code").
// transcriptPath is the path to the live transcript file (for mid-session commit detection).
func (s *AutoCommitStrategy) InitializeSession(sessionID string, agentType agent.AgentType, transcriptPath string) error {
	repo, err := OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get current HEAD commit to track as base
	head, err := repo.Head()
	if err != nil {
		return fmt.Errorf("failed to get HEAD: %w", err)
	}

	baseCommit := head.Hash().String()

	// Check if session state already exists (e.g., session resuming)
	existing, err := LoadSessionState(sessionID)
	if err != nil {
		return fmt.Errorf("failed to check existing session state: %w", err)
	}
	if existing != nil {
		// Session already initialized, nothing to do
		return nil
	}

	// Create new session state
	state := &SessionState{
		SessionID:                sessionID,
		BaseCommit:               baseCommit,
		StartedAt:                time.Now(),
		CheckpointCount:          0,
		CondensedTranscriptLines: 0, // Start from beginning of transcript
		FilesTouched:             []string{},
		AgentType:                agentType,
		TranscriptPath:           transcriptPath,
	}

	if err := SaveSessionState(state); err != nil {
		return fmt.Errorf("failed to save session state: %w", err)
	}

	return nil
}

// ListOrphanedItems returns orphaned items created by the auto-commit strategy.
// For auto-commit, checkpoints are orphaned when no commit has an Entire-Checkpoint
// trailer referencing them (e.g., after rebasing or squashing).
func (s *AutoCommitStrategy) ListOrphanedItems() ([]CleanupItem, error) {
	repo, err := OpenRepository()
	if err != nil {
		return nil, fmt.Errorf("failed to open repository: %w", err)
	}

	// Get checkpoint store (lazily initialized)
	cpStore, err := s.getCheckpointStore()
	if err != nil {
		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
	}

	// Get all checkpoints from entire/sessions branch
	checkpoints, err := cpStore.ListCommitted(context.Background())
	if err != nil {
		return []CleanupItem{}, nil //nolint:nilerr // No checkpoints is not an error for cleanup
	}

	if len(checkpoints) == 0 {
		return []CleanupItem{}, nil
	}

	// Filter to only auto-commit checkpoints (identified by strategy in metadata)
	autoCommitCheckpoints := make(map[string]bool)
	for _, cp := range checkpoints {
		result, readErr := cpStore.ReadCommitted(context.Background(), cp.CheckpointID)
		if readErr != nil || result == nil {
			continue
		}
		// Only consider checkpoints created by this strategy
		if result.Metadata.Strategy == StrategyNameAutoCommit || result.Metadata.Strategy == StrategyNameDual {
			autoCommitCheckpoints[cp.CheckpointID.String()] = true
		}
	}

	if len(autoCommitCheckpoints) == 0 {
		return []CleanupItem{}, nil
	}

	// Find checkpoint IDs referenced in commits
	referencedCheckpoints := s.findReferencedCheckpoints(repo)

	// Find orphaned checkpoints
	var items []CleanupItem
	for checkpointID := range autoCommitCheckpoints {
		if !referencedCheckpoints[checkpointID] {
			items = append(items, CleanupItem{
				Type:   CleanupTypeCheckpoint,
				ID:     checkpointID,
				Reason: "no commit references this checkpoint",
			})
		}
	}

	return items, nil
}

// findReferencedCheckpoints scans commits for Entire-Checkpoint trailers.
func (s *AutoCommitStrategy) findReferencedCheckpoints(repo *git.Repository) map[string]bool {
	referenced := make(map[string]bool)

	refs, err := repo.References()
	if err != nil {
		return referenced
	}

	visited := make(map[plumbing.Hash]bool)

	_ = refs.ForEach(func(ref *plumbing.Reference) error { //nolint:errcheck // Best effort
		if !ref.Name().IsBranch() {
			return nil
		}
		// Skip entire/* branches
		branchName := strings.TrimPrefix(ref.Name().String(), "refs/heads/")
		if strings.HasPrefix(branchName, "entire/") {
			return nil
		}

		iter, iterErr := repo.Log(&git.LogOptions{From: ref.Hash()})
		if iterErr != nil {
			return nil //nolint:nilerr // Best effort
		}

		count := 0
		_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best effort
			count++
			if count > 1000 {
				return errors.New("limit reached")
			}
			if visited[c.Hash] {
				return nil
			}
			visited[c.Hash] = true

			if cpID, found := trailers.ParseCheckpoint(c.Message); found {
				referenced[cpID.String()] = true
			}
			return nil

// calculatePromptAttributionAtStart calculates attribution at prompt start (before agent runs).
// This captures user changes since the last checkpoint - no filtering needed since
// the agent hasn't made any changes yet.
//
// IMPORTANT: This reads from the worktree (not staging area) to match what WriteTemporary
// captures in checkpoints. If we read staged content but checkpoints capture worktree content,
// unstaged changes would be in the checkpoint but not counted in PromptAttribution, causing
// them to be incorrectly attributed to the agent later.
func (s *ManualCommitStrategy) calculatePromptAttributionAtStart(
	repo *git.Repository,
	state *SessionState,
) PromptAttribution {
	logCtx := logging.WithComponent(context.Background(), "attribution")
	nextCheckpointNum := state.CheckpointCount + 1
	result := PromptAttribution{CheckpointNumber: nextCheckpointNum}

	// Get last checkpoint tree from shadow branch (if it exists)
	// For the first checkpoint, no shadow branch exists yet - this is fine,
	// CalculatePromptAttribution will use baseTree as the reference instead.
	var lastCheckpointTree *object.Tree
	shadowBranchName := checkpoint.ShadowBranchNameForCommit(state.BaseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		logging.Debug(logCtx, "prompt attribution: no shadow branch yet (first checkpoint)",
			slog.String("shadow_branch", shadowBranchName))
		// Continue with lastCheckpointTree = nil
	} else {
		shadowCommit, err := repo.CommitObject(ref.Hash())
		if err != nil {
			logging.Debug(logCtx, "prompt attribution: failed to get shadow commit",
				slog.String("shadow_ref", ref.Hash().String()),
				slog.String("error", err.Error()))
			// Continue with lastCheckpointTree = nil
		} else {
			lastCheckpointTree, err = shadowCommit.Tree()
			if err != nil {
				logging.Debug(logCtx, "prompt attribution: failed to get shadow tree",
					slog.String("error", err.Error()))
				// Continue with lastCheckpointTree = nil
			}
		}
	}

	// Get base tree for agent lines calculation
	var baseTree *object.Tree
	if baseCommit, err := repo.CommitObject(plumbing.NewHash(state.BaseCommit)); err == nil {
		if tree, treeErr := baseCommit.Tree(); treeErr == nil {
			baseTree = tree
		} else {
			logging.Debug(logCtx, "prompt attribution: base tree unavailable",
				slog.String("error", treeErr.Error()))
		}
	} else {
		logging.Debug(logCtx, "prompt attribution: base commit unavailable",
			slog.String("base_commit", state.BaseCommit),
			slog.String("error", err.Error()))
	}

	worktree, err := repo.Worktree()
	if err != nil {
		logging.Debug(logCtx, "prompt attribution skipped: failed to get worktree",
			slog.String("error", err.Error()))
		return result
	}

	// Get worktree status to find ALL changed files
	status, err := worktree.Status()
	if err != nil {
		logging.Debug(logCtx, "prompt attribution skipped: failed to get worktree status",
			slog.String("error", err.Error()))
		return result
	}

	worktreeRoot := worktree.Filesystem.Root()

	// Build map of changed files with their worktree content
	// IMPORTANT: We read from worktree (not staging area) to match what WriteTemporary
	// captures in checkpoints. This ensures attribution is consistent.
	changedFiles := make(map[string]string)
	for filePath, fileStatus := range status {
		// Skip unmodified files
		if fileStatus.Worktree == git.Unmodified && fileStatus.Staging == git.Unmodified {
			continue
		}
		// Skip .entire metadata directory (session data, not user code)
		if strings.HasPrefix(filePath, paths.EntireMetadataDir+"/") || strings.HasPrefix(filePath, ".entire/") {
			continue
		}

		// Always read from worktree to match checkpoint behavior
		fullPath := filepath.Join(worktreeRoot, filePath)
		var content string
		if data, err := os.ReadFile(fullPath); err == nil { //nolint:gosec // filePath is from git worktree status
			// Use git's binary detection algorithm (matches getFileContent behavior).
			// Binary files are excluded from line-based attribution calculations.
			isBinary, binErr := binary.IsBinary(bytes.NewReader(data))
			if binErr == nil && !isBinary {
				content = string(data)
			}

