   314→func CapturePreTaskState(toolUseID string) error {
   315→	if toolUseID == "" {
   316→		return errors.New("tool_use_id is required")
   317→	}
   318→
   319→	// Get absolute path for tmp directory
   320→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
