   356→
   357→// LoadPreTaskState loads previously captured task state.
   358→// Returns nil if no state file exists.
   359→func LoadPreTaskState(toolUseID string) (*PreTaskState, error) {
   360→	stateFile := preTaskStateFile(toolUseID)
   361→
   362→	if !fileExists(stateFile) {
