   387→
   388→// ComputeNewFilesFromTask compares current untracked files with pre-task state
   389→// to find files that were created during the task.
   390→func ComputeNewFilesFromTask(preState *PreTaskState) ([]string, error) {
   391→	if preState == nil {
   392→		return nil, nil
   393→	}
   394→
   395→	currentUntracked, err := getUntrackedFilesForState()
   396→	if err != nil {
   397→		return nil, err
   398→	}
   399→
   400→	return findNewUntrackedFiles(currentUntracked, preState.UntrackedFiles), nil
   401→}
   402→
   403→// computeNewFilesFromTaskState is a helper that doesn't need to query git
   404→// (used for testing)
   405→func computeNewFilesFromTaskState(preState *PreTaskState, currentFiles []string) []string {
   406→	if preState == nil {
