package cli

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/jsonutil"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/strategy"

	"github.com/go-git/go-git/v5"
)

// PrePromptState stores the state captured before a user prompt
type PrePromptState struct {
	SessionID      string   `json:"session_id"`
	Timestamp      string   `json:"timestamp"`
	UntrackedFiles []string `json:"untracked_files"`

	// StartMessageIndex is the message count in the transcript when this state
	// was captured. Used for calculating token usage since the prompt started.
	// Only set for Gemini sessions. Zero means not set or session just started.
	StartMessageIndex int `json:"start_message_index,omitempty"`

	// Transcript position at prompt start - tracks what was added during this checkpoint
	// Used for Claude Code sessions.
	LastTranscriptIdentifier string `json:"last_transcript_identifier,omitempty"` // Last identifier when prompt started (UUID for Claude, message ID for Gemini)
	LastTranscriptLineCount  int    `json:"last_transcript_line_count,omitempty"` // Line count when prompt started
}

// CapturePrePromptState captures current untracked files and transcript position before a prompt
// and saves them to a state file.
// Works correctly from any subdirectory within the repository.
// The transcriptPath parameter is optional - if empty, transcript position won't be captured.
func CapturePrePromptState(sessionID, transcriptPath string) error {
	if sessionID == "" {
		sessionID = unknownSessionID
	}

	// Get absolute path for tmp directory
	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
	if err != nil {
		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
	}

	// Create tmp directory if it doesn't exist
	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
		return fmt.Errorf("failed to create tmp directory: %w", err)
	}

	// Get list of untracked files (excluding .entire directory itself)
	untrackedFiles, err := getUntrackedFilesForState()
	if err != nil {
		return fmt.Errorf("failed to get untracked files: %w", err)
	}

	// Get transcript position (last UUID and line count)
	var transcriptPos TranscriptPosition
	if transcriptPath != "" {
		transcriptPos, err = GetTranscriptPosition(transcriptPath)
		if err != nil {
			// Log warning but don't fail - transcript position is optional
			fmt.Fprintf(os.Stderr, "Warning: failed to get transcript position: %v\n", err)
		}
	}

	// Create state file
	stateFile := prePromptStateFile(sessionID)
	state := PrePromptState{
		SessionID:                sessionID,
		Timestamp:                time.Now().UTC().Format(time.RFC3339),
		UntrackedFiles:           untrackedFiles,
		LastTranscriptIdentifier: transcriptPos.LastUUID,
		LastTranscriptLineCount:  transcriptPos.LineCount,
	}

	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal state: %w", err)
	}

	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
		return fmt.Errorf("failed to write state file: %w", err)
	}

	fmt.Fprintf(os.Stderr, "Captured state before prompt: %d untracked files, transcript at line %d (uuid: %s)\n",
		len(untrackedFiles), transcriptPos.LineCount, transcriptPos.LastUUID)
	return nil
}

// CaptureGeminiPrePromptState captures current untracked files and transcript position
// before a prompt for Gemini sessions. This is called by the BeforeAgent hook.
// The transcriptPath is the path to the Gemini session transcript (JSON format).
func CaptureGeminiPrePromptState(sessionID, transcriptPath string) error {
	if sessionID == "" {
		sessionID = unknownSessionID
	}

	// Get absolute path for tmp directory
	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
	if err != nil {
		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
	}

	// Create tmp directory if it doesn't exist
	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
		return fmt.Errorf("failed to create tmp directory: %w", err)
	}

	// Get list of untracked files (excluding .entire directory itself)
	untrackedFiles, err := getUntrackedFilesForState()
	if err != nil {
		return fmt.Errorf("failed to get untracked files: %w", err)
	}

	// Get transcript position (message count and last message ID) for Gemini
	var startMessageIndex int
	var lastMessageID string
	if transcriptPath != "" {
		// Read transcript and extract both message count and last message ID
		if data, readErr := os.ReadFile(transcriptPath); readErr == nil && len(data) > 0 { //nolint:gosec // Reading from controlled transcript path
			var transcript struct {
				Messages []struct {
					ID string `json:"id"`
				} `json:"messages"`
			}
			if jsonErr := json.Unmarshal(data, &transcript); jsonErr == nil {
				startMessageIndex = len(transcript.Messages)
				if startMessageIndex > 0 {
					lastMessageID = transcript.Messages[startMessageIndex-1].ID
				}
			} else {
				fmt.Fprintf(os.Stderr, "Warning: failed to parse transcript for message tracking: %v\n", jsonErr)
			}
		}
	}

	// Create state file
	stateFile := prePromptStateFile(sessionID)
	state := PrePromptState{
		SessionID:                sessionID,
		Timestamp:                time.Now().UTC().Format(time.RFC3339),
		UntrackedFiles:           untrackedFiles,
		StartMessageIndex:        startMessageIndex,
		LastTranscriptIdentifier: lastMessageID,
	}

	data, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal state: %w", err)
	}

	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
		return fmt.Errorf("failed to write state file: %w", err)
	}

	fmt.Fprintf(os.Stderr, "Captured Gemini state before prompt: %d untracked files, transcript position: %d (last msg id: %s)\n", len(untrackedFiles), startMessageIndex, lastMessageID)
	return nil
}

// LoadPrePromptState loads previously captured state.
// Returns nil if no state file exists.
func LoadPrePromptState(sessionID string) (*PrePromptState, error) {
	stateFile := prePromptStateFile(sessionID)

	if !fileExists(stateFile) {
		return nil, nil
	}

	data, err := os.ReadFile(stateFile) //nolint:gosec // Reading from controlled git metadata path
	if err != nil {
		return nil, fmt.Errorf("failed to read state file: %w", err)
	}

	var state PrePromptState
	if err := json.Unmarshal(data, &state); err != nil {
		return nil, fmt.Errorf("failed to unmarshal state: %w", err)
	}

	return &state, nil
}

// CleanupPrePromptState removes the state file after use
func CleanupPrePromptState(sessionID string) error {
	stateFile := prePromptStateFile(sessionID)
	if fileExists(stateFile) {
		return os.Remove(stateFile)
	}
	return nil
}

// ComputeNewFiles compares current untracked files with pre-prompt state
// to find files that were created during the session.
func ComputeNewFiles(preState *PrePromptState) ([]string, error) {
	if preState == nil {
		return nil, nil
	}

	currentUntracked, err := getUntrackedFilesForState()
	if err != nil {
		return nil, err
	}

	return findNewUntrackedFiles(currentUntracked, preState.UntrackedFiles), nil
}

// ComputeDeletedFiles returns files that were deleted during the session
// (tracked files that no longer exist).
func ComputeDeletedFiles() ([]string, error) {
	repo, err := openRepository()
	if err != nil {
		return nil, err
	}

	worktree, err := repo.Worktree()
	if err != nil {
		return nil, err
	}

	status, err := worktree.Status()
	if err != nil {
		return nil, err
	}

	var deletedFiles []string
	for file, st := range status {
		// Skip .entire directory
		if paths.IsInfrastructurePath(file) {
			continue
		}

		// Find deleted files that haven't been staged yet
		if st.Worktree == git.Deleted && st.Staging != git.Deleted {
			deletedFiles = append(deletedFiles, file)
		}
	}

	return deletedFiles, nil
}

// FilterAndNormalizePaths converts absolute paths to relative and filters out
// infrastructure paths and paths outside the repo.
func FilterAndNormalizePaths(files []string, cwd string) []string {
	var result []string
	for _, file := range files {
		relPath := paths.ToRelativePath(file, cwd)
		if relPath == "" {
			continue // outside repo
		}
		if paths.IsInfrastructurePath(relPath) {
			continue // skip .entire directory
		}
		result = append(result, relPath)
	}
	return result
}

// prePromptStateFile returns the absolute path to the pre-prompt state file for a session.
// Works correctly from any subdirectory within the repository.
func prePromptStateFile(sessionID string) string {
	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
	if err != nil {
		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
	}
	return filepath.Join(tmpDirAbs, fmt.Sprintf("pre-prompt-%s.json", sessionID))
}

// getUntrackedFilesForState returns a list of untracked files using go-git
// Excludes .entire directory
func getUntrackedFilesForState() ([]string, error) {
	repo, err := openRepository()
	if err != nil {
		return nil, err
	}

	worktree, err := repo.Worktree()
	if err != nil {
		return nil, err
	}

	status, err := worktree.Status()
	if err != nil {
		return nil, err
	}

	var untrackedFiles []string
	for file, st := range status {
		if st.Worktree == git.Untracked {
			// Exclude .entire directory
			if !strings.HasPrefix(file, paths.EntireDir+"/") && file != paths.EntireDir {
				untrackedFiles = append(untrackedFiles, file)
			}
		}
	}

	return untrackedFiles, nil
}

// PreTaskState stores the state captured before a task execution
type PreTaskState struct {
	ToolUseID      string   `json:"tool_use_id"`
	Timestamp      string   `json:"timestamp"`
	UntrackedFiles []string `json:"untracked_files"`
}

// CapturePreTaskState captures current untracked files before a Task execution
// and saves them to a state file.
// Works correctly from any subdirectory within the repository.
func CapturePreTaskState(toolUseID string) error {
	if toolUseID == "" {
		return errors.New("tool_use_id is required")
	}

	// Get absolute path for tmp directory
	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
	if err != nil {
		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
	}

	// Create tmp directory if it doesn't exist
	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
		return fmt.Errorf("failed to create tmp directory: %w", err)
	}

	// Get list of untracked files (excluding .entire directory itself)
	untrackedFiles, err := getUntrackedFilesForState()
	if err != nil {
		return fmt.Errorf("failed to get untracked files: %w", err)
	}

	// Create state file
	stateFile := preTaskStateFile(toolUseID)
	state := PreTaskState{
		ToolUseID:      toolUseID,
		Timestamp:      time.Now().UTC().Format(time.RFC3339),
		UntrackedFiles: untrackedFiles,
	}

	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal state: %w", err)
	}

	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
		return fmt.Errorf("failed to write state file: %w", err)
	}

	fmt.Fprintf(os.Stderr, "Captured state before task: %d untracked files\n", len(untrackedFiles))
	return nil
}

// LoadPreTaskState loads previously captured task state.
// Returns nil if no state file exists.
func LoadPreTaskState(toolUseID string) (*PreTaskState, error) {
	stateFile := preTaskStateFile(toolUseID)

	if !fileExists(stateFile) {
		return nil, nil
	}

	data, err := os.ReadFile(stateFile) //nolint:gosec // Reading from controlled git metadata path
	if err != nil {
		return nil, fmt.Errorf("failed to read state file: %w", err)
	}

	var state PreTaskState
	if err := json.Unmarshal(data, &state); err != nil {
		return nil, fmt.Errorf("failed to unmarshal state: %w", err)
	}

	return &state, nil
}

// CleanupPreTaskState removes the task state file after use
func CleanupPreTaskState(toolUseID string) error {
	stateFile := preTaskStateFile(toolUseID)
	if fileExists(stateFile) {
		return os.Remove(stateFile)
	}
	return nil
}

// ComputeNewFilesFromTask compares current untracked files with pre-task state
// to find files that were created during the task.
func ComputeNewFilesFromTask(preState *PreTaskState) ([]string, error) {
	if preState == nil {
		return nil, nil
	}

	currentUntracked, err := getUntrackedFilesForState()
	if err != nil {
		return nil, err
	}

	return findNewUntrackedFiles(currentUntracked, preState.UntrackedFiles), nil
}

// computeNewFilesFromTaskState is a helper that doesn't need to query git
// (used for testing)
func computeNewFilesFromTaskState(preState *PreTaskState, currentFiles []string) []string {
	if preState == nil {
		return nil
	}
	return findNewUntrackedFiles(currentFiles, preState.UntrackedFiles)
}

// preTaskStateFile returns the absolute path to the pre-task state file for a tool use.
// Works correctly from any subdirectory within the repository.
func preTaskStateFile(toolUseID string) string {
	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
	if err != nil {
		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
	}
	return filepath.Join(tmpDirAbs, fmt.Sprintf("pre-task-%s.json", toolUseID))
}

// preTaskFilePrefix is the prefix for pre-task state files
const preTaskFilePrefix = "pre-task-"

// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
// When multiple pre-task files exist (nested subagents), returns the most recently
// modified one.
// Works correctly from any subdirectory within the repository.
func FindActivePreTaskFile() (taskToolUseID string, found bool) {
	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
	if err != nil {
		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
	}
	entries, err := os.ReadDir(tmpDirAbs)
	if err != nil {
		return "", false
	}

	var latestFile string
	var latestTime time.Time

	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		name := entry.Name()
		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
			continue
		}

		// Check modification time for nested subagent handling
		info, err := entry.Info()
		if err != nil {
			continue
		}
		if latestFile == "" || info.ModTime().After(latestTime) {
			latestFile = name
			latestTime = info.ModTime()
		}
	}

	if latestFile == "" {
		return "", false
	}

	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
	toolUseID = strings.TrimSuffix(toolUseID, ".json")
	return toolUseID, true
}

// DetectChangedFiles detects files that have been modified, added, or deleted
// since the last commit (or compared to the index for incremental checkpoints).
// Returns three slices: modified files, new (untracked) files, and deleted files.
// Excludes .entire/ directory from all results.
func DetectChangedFiles() (modified, newFiles, deleted []string, err error) {
	repo, err := openRepository()
	if err != nil {
		return nil, nil, nil, fmt.Errorf("failed to open repository: %w", err)
	}

	worktree, err := repo.Worktree()
	if err != nil {
		return nil, nil, nil, fmt.Errorf("failed to get worktree: %w", err)
	}

	status, err := worktree.Status()
	if err != nil {
		return nil, nil, nil, fmt.Errorf("failed to get status: %w", err)
	}

	for file, st := range status {
		// Skip .entire directory
		if paths.IsInfrastructurePath(file) {
			continue
		}

		// Handle different status codes
		// Worktree status indicates changes not yet staged
		// Staging status indicates changes staged for commit
		switch {
		case st.Worktree == git.Untracked:
			// New untracked file
			newFiles = append(newFiles, file)
		case st.Worktree == git.Deleted || st.Staging == git.Deleted:
			// Deleted file
			deleted = append(deleted, file)
		case st.Worktree == git.Modified || st.Staging == git.Modified ||
			st.Worktree == git.Added || st.Staging == git.Added:
			// Modified or staged file
			modified = append(modified, file)
		}
	}

	return modified, newFiles, deleted, nil
}

// GetNextCheckpointSequence returns the next sequence number for incremental checkpoints.
// It counts existing checkpoint files in the task metadata checkpoints directory.
// Returns 1 if no checkpoints exist yet.
func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
	// ctx.SessionID is already an Entire session ID (date-prefixed), so use SessionMetadataDirFromEntireID
	sessionMetadataDir := paths.SessionMetadataDirFromEntireID(sessionID)
	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")

	entries, err := os.ReadDir(checkpointsDir)
	if err != nil {
		// Directory doesn't exist or can't be read - start at 1
		return 1
	}

	// Count JSON files (checkpoints)
	count := 0
	for _, entry := range entries {
		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
			count++
		}
	}

	return count + 1
}

// Package strategy provides an interface for different git strategies
// that can be used to save and manage Claude Code session changes.
package strategy

import (
	"encoding/json"
	"errors"
	"os"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint/id"
)

// ErrNoMetadata is returned when a commit does not have an Entire metadata trailer.
var ErrNoMetadata = errors.New("commit has no entire metadata")

// ErrNoSession is returned when no session info is available.
var ErrNoSession = errors.New("no session info available")

// ErrNotTaskCheckpoint is returned when a rewind point is not a task checkpoint.
var ErrNotTaskCheckpoint = errors.New("not a task checkpoint")

// ErrNotImplemented is returned when a feature is not yet implemented.
var ErrNotImplemented = errors.New("not implemented")

// ShadowBranchConflictError is returned when a shadow branch already exists
// with activity from a different session or worktree.
type ShadowBranchConflictError struct {
	Branch           string    // The shadow branch name (e.g., "entire/abc1234")
	ExistingSession  string    // Session ID of the existing session
	ExistingWorktree string    // Worktree path of the existing session
	LastActivity     time.Time // When the existing session was last active
	CurrentSession   string    // Session ID of the current session attempting to start
	CurrentWorktree  string    // Worktree path of the current session
}

func (e *ShadowBranchConflictError) Error() string {
	return "shadow branch conflict: existing session from different worktree"
}

// SessionIDConflictError is returned when trying to start a new session
// but the shadow branch already has commits from a different session ID.
// This prevents orphaning existing session work.
type SessionIDConflictError struct {
	ExistingSession string // Session ID found in the shadow branch
	NewSession      string // Session ID being initialized
	ShadowBranch    string // The shadow branch name (e.g., "entire/abc1234")
}

func (e *SessionIDConflictError) Error() string {
	return "session ID conflict: shadow branch has commits from a different session"
}

// ExtractToolUseIDFromTaskMetadataDir extracts the ToolUseID from a task metadata directory path.
// Task metadata dirs have format: .entire/metadata/<session>/tasks/<toolUseID>
// Returns empty string if not a task metadata directory.
func ExtractToolUseIDFromTaskMetadataDir(metadataDir string) string {
	parts := strings.Split(metadataDir, "/")
	if len(parts) >= 2 && parts[len(parts)-2] == "tasks" {
		return parts[len(parts)-1]
	}
	return ""
}

// SessionInfo contains information about the current session state.
// This is used to generate trailers for linking commits to their AI session.
type SessionInfo struct {
	// SessionID is the session identifier extracted from the latest commit's metadata
	SessionID string

	// Reference is a strategy-specific reference string.
	// For manual-commit strategy: "entire/abc1234" (the shadow branch name)
	// Empty for commit strategy (metadata is in the same commit).
	Reference string

	// CommitHash is the full SHA of the commit containing the session metadata.
	// Empty for commit strategy.
	CommitHash string
}

// RewindPoint represents a point to which the user can rewind.
// This abstraction allows different strategies to use different
// identifiers (commit hashes, branch names, stash refs, etc.)
type RewindPoint struct {
	// ID is the unique identifier for this rewind point
	// (commit hash, branch name, stash ref, etc.)
	ID string

	// Message is the human-readable description/summary
	Message string

	// MetadataDir is the path to the metadata directory
	MetadataDir string

	// Date is when this rewind point was created
	Date time.Time

	// IsTaskCheckpoint indicates if this is a task checkpoint (vs a session checkpoint)
	IsTaskCheckpoint bool

	// ToolUseID is the tool use ID for task checkpoints (empty for session checkpoints)
	ToolUseID string

	// IsLogsOnly indicates this is a commit with session logs but no shadow branch state.
	// The logs can be restored from entire/sessions, but file state requires git checkout.
	IsLogsOnly bool

	// CheckpointID is the stable 12-hex-char identifier for logs-only points.
	// Used to retrieve logs from entire/sessions/<id[:2]>/<id[2:]>/full.jsonl
	// Empty for shadow branch checkpoints (uncommitted).
	CheckpointID id.CheckpointID

	// Agent is the human-readable name of the agent that created this checkpoint
	// (e.g., "Claude Code", "Cursor")
	Agent agent.AgentType

	// SessionID is the session identifier for this checkpoint.
	// Used to distinguish checkpoints from different concurrent sessions.
	SessionID string

	// SessionPrompt is the initial prompt that started this session.
	// Used to help users identify which session a checkpoint belongs to.
	SessionPrompt string

	// SessionCount is the number of sessions in this checkpoint (1 for single-session).
	// Only populated for logs-only points with multi-session checkpoints.
	SessionCount int

	// SessionIDs contains all session IDs when this is a multi-session checkpoint.
	// The last entry is the most recent session (same as SessionID).
	// Only populated for logs-only points with multi-session checkpoints.
	SessionIDs []string

	// SessionPrompts contains the first prompt for each session (parallel to SessionIDs).
	// Used to display context when showing resume commands for multi-session checkpoints.
	SessionPrompts []string
}

// RewindPreview describes what will happen when rewinding to a checkpoint.
// Used to warn users about files that will be modified or deleted.
type RewindPreview struct {
	// FilesToRestore are files from the checkpoint that will be written/restored.
	FilesToRestore []string

	// FilesToDelete are untracked files that will be removed.
	// These are files created after the checkpoint that aren't in the checkpoint tree
	// and weren't present at session start.
	FilesToDelete []string

	// TrackedChanges are tracked files with uncommitted changes that will be reverted.
	// These come from the existing CanRewind() warning.
	TrackedChanges []string
}

// SaveContext contains all information needed for saving changes.
// All file paths should be pre-filtered and normalized by the CLI layer.
type SaveContext struct {
	// SessionID is the Claude Code session identifier
	SessionID string

	// ModifiedFiles is the list of files modified during the session
	// (extracted from the transcript, already filtered and relative)
	ModifiedFiles []string

	// NewFiles is the list of new files created during the session
	// (pre-computed by CLI from pre-prompt state comparison)
	NewFiles []string

	// DeletedFiles is the list of files deleted during the session
	// (tracked files that no longer exist)
	DeletedFiles []string

	// MetadataDir is the path to the session metadata directory
	MetadataDir string

	// MetadataDirAbs is the absolute path to the session metadata directory
	MetadataDirAbs string

	// CommitMessage is the generated commit message
	CommitMessage string

	// TranscriptPath is the path to the transcript file
	TranscriptPath string

	// AuthorName is the name to use for commits
	AuthorName string

	// AuthorEmail is the email to use for commits
	AuthorEmail string

	// AgentType is the human-readable agent name (e.g., "Claude Code", "Cursor")
	AgentType agent.AgentType

	// Transcript position at checkpoint start - tracks what was added during this checkpoint
	TranscriptIdentifierAtStart string // Last identifier when checkpoint started (UUID for Claude, message ID for Gemini)
	TranscriptLinesAtStart      int    // Line count when checkpoint started

	// TokenUsage contains the token usage for this checkpoint
	TokenUsage *agent.TokenUsage
}

// TaskCheckpointContext contains all information needed for saving a task checkpoint.
// This is called by the PostToolUse[Task] hook when a subagent completes.
// The strategy is responsible for creating metadata structures and storing them
// according to its storage approach.
type TaskCheckpointContext struct {
	// SessionID is the Claude Code session identifier
	SessionID string

	// ToolUseID is the unique identifier for this Task tool invocation
	ToolUseID string

	// AgentID is the subagent identifier (from tool_response.agentId)
	AgentID string

	// ModifiedFiles is the list of files modified by the subagent
	// (extracted from the subagent's transcript)
	ModifiedFiles []string

	// NewFiles is the list of new files created by the subagent
	// (computed from pre-task state comparison)
	NewFiles []string

	// DeletedFiles is the list of files deleted by the subagent
	DeletedFiles []string

	// TranscriptPath is the path to the main session transcript
	TranscriptPath string

	// SubagentTranscriptPath is the path to the subagent's transcript (if available)
	SubagentTranscriptPath string

	// CheckpointUUID is the UUID for transcript truncation when rewinding
	CheckpointUUID string

	// AuthorName is the name to use for commits
	AuthorName string

	// AuthorEmail is the email to use for commits
	AuthorEmail string

	// IsIncremental indicates this is an incremental checkpoint during task execution,
	// not a final task completion checkpoint. When true:
	// - Writes to checkpoints/NNN-{tool-use-id}.json instead of checkpoint.json
	// - Skips transcript handling
	// - Uses incremental commit message
	IsIncremental bool

	// IncrementalSequence is the checkpoint sequence number (1, 2, 3, ...)
	// Only used when IsIncremental is true
	IncrementalSequence int

	// IncrementalType is the tool that triggered this checkpoint ("TodoWrite", "Edit", etc.)
	// Only used when IsIncremental is true
	IncrementalType string

	// IncrementalData is the tool_input payload for this checkpoint
	// Only used when IsIncremental is true
	IncrementalData json.RawMessage

	// SubagentType is the type of subagent (e.g., "dev", "reviewer")
	// Extracted from tool_input.subagent_type in Task tool
	// Used for descriptive commit messages
	SubagentType string

	// TaskDescription is the task description provided to the subagent
	// Extracted from tool_input.description in Task tool
	// Used for descriptive commit messages
	TaskDescription string

	// TodoContent is the content of the in-progress todo item
	// Extracted from tool_input.todos where status == "in_progress"
	// Used for descriptive incremental checkpoint messages
	TodoContent string

	// AgentType is the human-readable agent name (e.g., "Claude Code", "Cursor")
	AgentType agent.AgentType
}

// TaskCheckpoint contains the checkpoint information written to checkpoint.json
type TaskCheckpoint struct {
	SessionID      string `json:"session_id"`
	ToolUseID      string `json:"tool_use_id"`
	CheckpointUUID string `json:"checkpoint_uuid"`
	AgentID        string `json:"agent_id,omitempty"`
}

// SubagentCheckpoint represents an intermediate checkpoint created during subagent execution.
// These are created by PostToolUse hooks for tools like TodoWrite, Edit, Write.
type SubagentCheckpoint struct {
	Type      string          `json:"type"`        // Tool name: "TodoWrite", "Edit", "Write"
	ToolUseID string          `json:"tool_use_id"` // The tool use ID that created this checkpoint
	Timestamp time.Time       `json:"timestamp"`   // When the checkpoint was created
	Data      json.RawMessage `json:"data"`        // Type-specific payload (tool_input)
}

// TaskMetadataDir returns the path to a task's metadata directory
// within the session metadata directory.
func TaskMetadataDir(sessionMetadataDir, toolUseID string) string {
	return sessionMetadataDir + "/tasks/" + toolUseID
}

// ReadTaskCheckpoint reads the checkpoint.json file from a task metadata directory.
// This is used during rewind to get the checkpoint UUID for transcript truncation.
func ReadTaskCheckpoint(taskMetadataDir string) (*TaskCheckpoint, error) {
	checkpointFile := taskMetadataDir + "/checkpoint.json"

	data, err := os.ReadFile(checkpointFile) //nolint:gosec // Reading from controlled git metadata path
	if err != nil {
		return nil, err
	}

	var checkpoint TaskCheckpoint
	if err := json.Unmarshal(data, &checkpoint); err != nil {
		return nil, err
	}

	return &checkpoint, nil
}

// Strategy defines the interface for git operation strategies.
// Different implementations can use commits, branches, stashes, etc.
//
// Note: State capture (tracking untracked files before a session) is handled
// by the CLI layer, not the strategy. The strategy receives pre-computed
// file lists in SaveContext.
type Strategy interface {
	// Name returns the strategy identifier (e.g., "commit", "branch", "stash")
	Name() string

	// Description returns a human-readable description for the setup wizard
	Description() string

	// AllowsMainBranch returns true if this strategy can safely operate on the
	// default branch (main/master). Strategies that don't modify the working
	// branch's commit history (like manual-commit strategies) can return true.
	// Strategies that create commits on the working branch should return false
	// to prevent polluting main branch history.
	AllowsMainBranch() bool

	// ValidateRepository checks if the repository is in a valid state
	// for this strategy to operate. Returns an error if validation fails.
	ValidateRepository() error

	// SaveChanges is called on Stop to save all session changes
	// using this strategy's approach (commit, branch, stash, etc.)
	SaveChanges(ctx SaveContext) error

	// SaveTaskCheckpoint is called by PostToolUse[Task] hook when a subagent completes.
	// Creates a checkpoint commit with task metadata for later rewind.
	// Different strategies may handle this differently:
	// - Commit strategy: commits to active branch
	// - Manual-commit strategy: commits to shadow branch
	// - Auto-commit strategy: commits logs to shadow only (code deferred to Stop)
	SaveTaskCheckpoint(ctx TaskCheckpointContext) error

	// GetRewindPoints returns available points to rewind to.
	// The limit parameter controls the maximum number of points to return.
	GetRewindPoints(limit int) ([]RewindPoint, error)

	// Rewind restores the repository to the given rewind point.
	// The metadataDir in the point is used to restore the session transcript.
	Rewind(point RewindPoint) error

	// CanRewind checks if rewinding is currently possible.
	// Returns (canRewind, reason if not, error)
	CanRewind() (bool, string, error)

	// PreviewRewind returns what will happen if rewinding to the given point.
	// This allows showing warnings about files that will be deleted before the rewind.
	// Returns nil if preview is not supported (e.g., auto-commit strategy).
	PreviewRewind(point RewindPoint) (*RewindPreview, error)

	// GetTaskCheckpoint returns the task checkpoint for a given rewind point.
	// For strategies that store checkpoints in git (auto-commit), this reads from the branch.
	// For strategies that store checkpoints on disk (commit, manual-commit), this reads from the filesystem.
	// Returns nil, nil if not a task checkpoint or checkpoint not found.
	GetTaskCheckpoint(point RewindPoint) (*TaskCheckpoint, error)

	// GetTaskCheckpointTranscript returns the session transcript for a task checkpoint.
	// For strategies that store transcripts in git (auto-commit), this reads from the branch.
	// For strategies that store transcripts on disk (commit, manual-commit), this reads from the filesystem.
	GetTaskCheckpointTranscript(point RewindPoint) ([]byte, error)

	// GetSessionInfo returns session information for linking commits.
	// This is used by the context command to generate trailers.
	// Returns ErrNoSession if no session info is available.
	GetSessionInfo() (*SessionInfo, error)

	// EnsureSetup ensures the strategy's required setup is in place,
	// installing any missing pieces (git hooks, gitignore entries, etc.).
	// Returns nil if setup is complete or was successfully installed.
	EnsureSetup() error

	// NOTE: ListSessions and GetSession are standalone functions in session.go.
	// They read from entire/sessions and merge with SessionSource if implemented.

	// GetMetadataRef returns a reference to the metadata commit for the given checkpoint.
	// Format: "<branch>@<commit-sha>" (e.g., "entire/sessions@abc123").
	// Returns empty string if not applicable (e.g., commit strategy with filesystem metadata).
	GetMetadataRef(checkpoint Checkpoint) string

	// GetSessionMetadataRef returns a reference to the most recent metadata commit for a session.
	// Format: "<branch>@<commit-sha>" (e.g., "entire/sessions@abc123").
	// Returns empty string if not applicable or session not found.
	GetSessionMetadataRef(sessionID string) string

	// GetSessionContext returns the context.md content for a session.
	// Returns empty string if not available.
	GetSessionContext(sessionID string) string

	// GetCheckpointLog returns the session transcript for a specific checkpoint.
	// For strategies that store transcripts in git branches (auto-commit, manual-commit),
	// this reads from the checkpoint's commit tree.
	// For strategies that store on disk (commit), reads from the filesystem.
	// Returns ErrNoMetadata if transcript is not available.
	GetCheckpointLog(checkpoint Checkpoint) ([]byte, error)
}

// SessionInitializer is an optional interface for strategies that need to
// initialize session state when a user prompt is submitted.
// Strategies like manual-commit use this to create session state files that
// the git prepare-commit-msg hook can detect.
type SessionInitializer interface {
	// InitializeSession creates session state for a new session.
	// Called during UserPromptSubmit hook before any checkpoints are created.
	// agentType is the human-readable name of the agent (e.g., "Claude Code").
	// transcriptPath is the path to the live transcript file (for mid-session commit detection).
	InitializeSession(sessionID string, agentType agent.AgentType, transcriptPath string) error
}

// PrepareCommitMsgHandler is an optional interface for strategies that need to
// handle the git prepare-commit-msg hook.
type PrepareCommitMsgHandler interface {
	// PrepareCommitMsg is called by the git prepare-commit-msg hook.
	// It can modify the commit message file to add trailers, etc.
	// The source parameter indicates how the commit was initiated:
	//   - "" or "template": normal editor flow
	//   - "message": using -m or -F flag
	//   - "merge": merge commit
	//   - "squash": squash merge
	//   - "commit": amend with -c/-C
	// Should return nil on errors to not block commits (log warnings to stderr).
	PrepareCommitMsg(commitMsgFile string, source string) error
}

// PostCommitHandler is an optional interface for strategies that need to
// handle the git post-commit hook.
type PostCommitHandler interface {
	// PostCommit is called by the git post-commit hook after a commit is created.
	// Used to perform actions like condensing session data after commits.
	// Should return nil on errors to not block subsequent operations (log warnings to stderr).
	PostCommit() error
}

// CommitMsgHandler is an optional interface for strategies that need to
// handle the git commit-msg hook.
type CommitMsgHandler interface {
	// CommitMsg is called by the git commit-msg hook after the user edits the message.
	// Used to validate or modify the final commit message before the commit is created.
	// If this returns an error, the commit is aborted.
	CommitMsg(commitMsgFile string) error
}

// PrePushHandler is an optional interface for strategies that need to
// handle the git pre-push hook.
type PrePushHandler interface {
	// PrePush is called by the git pre-push hook before pushing to a remote.
	// Used to push session branches (e.g., entire/sessions) alongside user pushes.
	// The remote parameter is the name of the remote being pushed to.
	// Should return nil on errors to not block pushes (log warnings to stderr).
	PrePush(remote string) error
}

// LogsOnlyRestorer is an optional interface for strategies that support
// restoring session logs without file state restoration.
// This is used for "logs-only" rewind points where only the session transcript
// can be restored (file state requires git checkout).
type LogsOnlyRestorer interface {
	// RestoreLogsOnly restores session logs from a logs-only rewind point.
	// Does not modify the working directory - only restores the transcript
	// to Claude's project directory.
	// If force is false, prompts for confirmation when local logs have newer timestamps.
	RestoreLogsOnly(point RewindPoint, force bool) error
}

// SessionResetter is an optional interface for strategies that support
// resetting session state and shadow branches.
// This is used by the "rewind reset" command to clean up shadow branches
// and session state when a user wants to start fresh.
type SessionResetter interface {
	// Reset deletes the shadow branch and session state for the current HEAD.
	// Returns nil if there's nothing to reset (no shadow branch).
	// The force parameter suppresses confirmation prompts.
	Reset(force bool) error
}

// ConcurrentSessionChecker is an optional interface for strategies that support
// detecting and warning about concurrent sessions with uncommitted changes.
// This is used by the UserPromptSubmit hook to block the first prompt when
// another session has uncommitted checkpoints on the same base commit.
type ConcurrentSessionChecker interface {
	// HasOtherActiveSessionsWithCheckpoints returns a session state if there's another
	// active session with uncommitted checkpoints on the same base commit.
	// Returns nil, nil if no such session exists.
	HasOtherActiveSessionsWithCheckpoints(currentSessionID string) (*SessionState, error)
}

// SessionSource is an optional interface for strategies that provide additional
// sessions beyond those stored on the entire/sessions branch.
// For example, manual-commit strategy provides active sessions from .git/entire-sessions/
// that haven't yet been condensed to entire/sessions.
//
// ListSessions() automatically discovers all registered strategies, checks if they
// implement SessionSource, and merges their additional sessions by ID.
type SessionSource interface {
	// GetAdditionalSessions returns sessions not yet on entire/sessions branch.
	GetAdditionalSessions() ([]*Session, error)
}

// OrphanedItemsLister is an optional interface for strategies that can identify
// orphaned items (shadow branches, session states, checkpoints) that should be
// cleaned up. This is used by the "entire session cleanup" command.
//
// ListAllCleanupItems() automatically discovers all registered strategies, checks
// if they implement OrphanedItemsLister, and combines their orphaned items.
type OrphanedItemsLister interface {
	// ListOrphanedItems returns items created by this strategy that are now orphaned.
	// Each strategy defines what "orphaned" means for its own data structures.
	ListOrphanedItems() ([]CleanupItem, error)
}

package strategy

import (
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint/id"
)

const (
	// sessionStateDirName is the directory name for session state files within git common dir.
	sessionStateDirName = "entire-sessions"

	// logsOnlyScanLimit is the maximum number of commits to scan for logs-only points.
	logsOnlyScanLimit = 50
)

// SessionState represents the state of an active session.
type SessionState struct {
	SessionID                string          `json:"session_id"`
	BaseCommit               string          `json:"base_commit"`
	WorktreePath             string          `json:"worktree_path,omitempty"` // Absolute path to the worktree root
	StartedAt                time.Time       `json:"started_at"`
	CheckpointCount          int             `json:"checkpoint_count"`
	CondensedTranscriptLines int             `json:"condensed_transcript_lines,omitempty"` // Lines already included in previous condensation
	UntrackedFilesAtStart    []string        `json:"untracked_files_at_start,omitempty"`   // Files that existed at session start (to preserve during rewind)
	FilesTouched             []string        `json:"files_touched,omitempty"`              // Files modified/created/deleted during this session
	ConcurrentWarningShown   bool            `json:"concurrent_warning_shown,omitempty"`   // True if user was warned about concurrent sessions
	LastCheckpointID         id.CheckpointID `json:"last_checkpoint_id,omitempty"`         // Checkpoint ID from last condensation, reused for subsequent commits without new content
	AgentType                agent.AgentType `json:"agent_type,omitempty"`                 // Agent type identifier (e.g., "Claude Code", "Cursor")
	TranscriptPath           string          `json:"transcript_path,omitempty"`            // Path to the live transcript file (for mid-session commit detection)

	// Token usage tracking (accumulated across all checkpoints in this session)
	TokenUsage *agent.TokenUsage `json:"token_usage,omitempty"`

	// Transcript position when session started (for multi-session checkpoints on entire/sessions)
	TranscriptLinesAtStart      int    `json:"transcript_lines_at_start,omitempty"`
	TranscriptIdentifierAtStart string `json:"transcript_identifier_at_start,omitempty"`

	// PromptAttributions tracks user and agent line changes at each prompt start.
	PromptAttributions []PromptAttribution `json:"prompt_attributions,omitempty"`

	// PendingPromptAttribution holds attribution calculated at prompt start (before agent runs).
	// This is moved to PromptAttributions when SaveChanges is called.
	PendingPromptAttribution *PromptAttribution `json:"pending_prompt_attribution,omitempty"`
}

// PromptAttribution captures line-level attribution data at the start of each prompt,
// calculated BEFORE the agent runs. This allows us to separate user edits (made between
// prompts) from agent edits (made during prompt execution).
//
// Fields:
//   - CheckpointNumber: Which checkpoint this attribution is for (1-indexed)
//   - UserLinesAdded/Removed: User edits since the last checkpoint (lastCheckpoint → worktree)
//   - AgentLinesAdded/Removed: Cumulative agent work so far (base → lastCheckpoint)
//   - UserAddedPerFile: Per-file breakdown of user additions (for accurate modification tracking)
//
// Note: For checkpoint 1, AgentLinesAdded/Removed are always 0 because there is no previous
// checkpoint to compare against. This doesn't mean the agent hasn't done work yet - it means
// we can't measure cumulative agent work until after the first checkpoint is created.
// These fields become meaningful starting from checkpoint 2.
//
// UserAddedPerFile enables accurate tracking of user self-modifications. When a user modifies
// their own previously-added lines (not agent lines), we shouldn't subtract from the agent's
// contribution. See docs/architecture/attribution.md for details.
type PromptAttribution struct {
	CheckpointNumber            int            `json:"checkpoint_number"`
	UserLinesAdded              int            `json:"user_lines_added"`
	UserLinesRemoved            int            `json:"user_lines_removed"`
	AgentLinesAdded             int            `json:"agent_lines_added"`             // Always 0 for checkpoint 1 (no previous checkpoint)
	AgentLinesRemoved           int            `json:"agent_lines_removed"`           // Always 0 for checkpoint 1 (no previous checkpoint)
	UserAddedPerFile            map[string]int `json:"user_added_per_file,omitempty"` // Per-file user additions for modification tracking
	TranscriptLinesAtStart      int            `json:"transcript_lines_at_start,omitempty"`
	TranscriptIdentifierAtStart string         `json:"transcript_identifier_at_start,omitempty"`
}

// CheckpointInfo represents checkpoint metadata stored on the sessions branch.
// Metadata is stored at sharded path: <checkpoint_id[:2]>/<checkpoint_id[2:]>/
type CheckpointInfo struct {
	CheckpointID     id.CheckpointID `json:"checkpoint_id"` // 12-hex-char from Entire-Checkpoint trailer, used as directory path
	SessionID        string          `json:"session_id"`
	CreatedAt        time.Time       `json:"created_at"`
	CheckpointsCount int             `json:"checkpoints_count"`
	FilesTouched     []string        `json:"files_touched"`
	Agent            agent.AgentType `json:"agent,omitempty"` // Human-readable agent name (e.g., "Claude Code")
	IsTask           bool            `json:"is_task,omitempty"`
	ToolUseID        string          `json:"tool_use_id,omitempty"`
	SessionCount     int             `json:"session_count,omitempty"` // Number of sessions (1 if omitted)
	SessionIDs       []string        `json:"session_ids,omitempty"`   // All session IDs in this checkpoint
}

// CondenseResult contains the result of a session condensation operation.
type CondenseResult struct {
	CheckpointID         id.CheckpointID // 12-hex-char from Entire-Checkpoint trailer, used as directory path
	SessionID            string
	CheckpointsCount     int
	FilesTouched         []string
	TotalTranscriptLines int // Total lines in transcript after this condensation
}

// ExtractedSessionData contains data extracted from a shadow branch.
type ExtractedSessionData struct {
	Transcript          []byte   // Full transcript content for the session
	FullTranscriptLines int      // Total line count in full transcript
	Prompts             []string // All user prompts from this portion
	Context             []byte   // Generated context.md content
	FilesTouched        []string
	TokenUsage          *agent.TokenUsage // Token usage calculated from transcript (since TranscriptLinesAtStart)
}

package session

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint/id"
	"entire.io/cli/cmd/entire/cli/jsonutil"
	"entire.io/cli/cmd/entire/cli/logging"
	"entire.io/cli/cmd/entire/cli/sessionid"
	"entire.io/cli/cmd/entire/cli/validation"
)

const (
	// sessionStateDirName is the directory name for session state files within git common dir.
	sessionStateDirName = "entire-sessions"
)

// State represents the state of an active session.
// This is stored in .git/entire-sessions/<session-id>.json
type State struct {
	// SessionID is the unique session identifier
	SessionID string `json:"session_id"`

	// BaseCommit is the HEAD commit when the session started
	BaseCommit string `json:"base_commit"`

	// WorktreePath is the absolute path to the worktree root
	WorktreePath string `json:"worktree_path,omitempty"`

	// StartedAt is when the session was started
	StartedAt time.Time `json:"started_at"`

	// CheckpointCount is the number of checkpoints created in this session
	CheckpointCount int `json:"checkpoint_count"`

	// CondensedTranscriptLines tracks lines already included in previous condensation
	CondensedTranscriptLines int `json:"condensed_transcript_lines,omitempty"`

	// UntrackedFilesAtStart tracks files that existed at session start (to preserve during rewind)
	UntrackedFilesAtStart []string `json:"untracked_files_at_start,omitempty"`

	// FilesTouched tracks files modified/created/deleted during this session
	FilesTouched []string `json:"files_touched,omitempty"`

	// ConcurrentWarningShown is true if user was warned about concurrent sessions
	ConcurrentWarningShown bool `json:"concurrent_warning_shown,omitempty"`

	// LastCheckpointID is the checkpoint ID from last condensation, reused for subsequent commits without new content
	LastCheckpointID id.CheckpointID `json:"last_checkpoint_id,omitempty"`

	// AgentType identifies the agent that created this session (e.g., "Claude Code", "Gemini CLI", "Cursor")
	AgentType agent.AgentType `json:"agent_type,omitempty"`

	// Token usage tracking (accumulated across all checkpoints in this session)
	TokenUsage *agent.TokenUsage `json:"token_usage,omitempty"`

	// Transcript position when session started (for multi-session checkpoints)
	TranscriptLinesAtStart      int    `json:"transcript_lines_at_start,omitempty"`
	TranscriptIdentifierAtStart string `json:"transcript_identifier_at_start,omitempty"`

	// TranscriptPath is the path to the live transcript file (for mid-session commit detection)
	TranscriptPath string `json:"transcript_path,omitempty"`

	// PromptAttributions tracks user and agent line changes at each prompt start.
	// This enables accurate attribution by capturing user edits between checkpoints.
	PromptAttributions []PromptAttribution `json:"prompt_attributions,omitempty"`

	// PendingPromptAttribution holds attribution calculated at prompt start (before agent runs).
	// This is moved to PromptAttributions when SaveChanges is called.
	PendingPromptAttribution *PromptAttribution `json:"pending_prompt_attribution,omitempty"`
}

// PromptAttribution captures line-level attribution data at the start of each prompt.
// By recording what changed since the last checkpoint BEFORE the agent works,
// we can accurately separate user edits from agent contributions.
type PromptAttribution struct {
	// CheckpointNumber is which checkpoint this was recorded before (1-indexed)
	CheckpointNumber int `json:"checkpoint_number"`

	// UserLinesAdded is lines added by user since the last checkpoint
	UserLinesAdded int `json:"user_lines_added"`

	// UserLinesRemoved is lines removed by user since the last checkpoint
	UserLinesRemoved int `json:"user_lines_removed"`

	// AgentLinesAdded is total agent lines added so far (base → last checkpoint).
	// Always 0 for checkpoint 1 since there's no previous checkpoint to measure against.
	AgentLinesAdded int `json:"agent_lines_added"`

	// AgentLinesRemoved is total agent lines removed so far (base → last checkpoint).
	// Always 0 for checkpoint 1 since there's no previous checkpoint to measure against.
	AgentLinesRemoved int `json:"agent_lines_removed"`

	// UserAddedPerFile tracks per-file user additions for accurate modification tracking.
	// This enables distinguishing user self-modifications from agent modifications.
	// See docs/architecture/attribution.md for details.
	UserAddedPerFile map[string]int `json:"user_added_per_file,omitempty"`
}

// StateStore provides low-level operations for managing session state files.
//
// StateStore is a primitive for session state persistence. It is NOT the same as
// the Sessions interface - it only handles state files in .git/entire-sessions/,
// not the full session data which includes checkpoint content.
//
// Use StateStore directly in strategies for performance-critical state operations.
// Use the Sessions interface (when implemented) for high-level session management.
type StateStore struct {
	// stateDir is the directory where session state files are stored
	stateDir string
}

// NewStateStore creates a new state store.
// Uses the git common dir to store session state (shared across worktrees).
func NewStateStore() (*StateStore, error) {
	commonDir, err := getGitCommonDir()
	if err != nil {
		return nil, fmt.Errorf("failed to get git common dir: %w", err)
	}
	return &StateStore{
		stateDir: filepath.Join(commonDir, sessionStateDirName),
	}, nil
}

// NewStateStoreWithDir creates a new state store with a custom directory.
// This is useful for testing.
func NewStateStoreWithDir(stateDir string) *StateStore {
	return &StateStore{stateDir: stateDir}
}

// Load loads the session state for the given session ID.
// Returns (nil, nil) when session file doesn't exist (not an error condition).
func (s *StateStore) Load(ctx context.Context, sessionID string) (*State, error) {
	_ = ctx // Reserved for future use

	// Validate session ID to prevent path traversal
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return nil, fmt.Errorf("invalid session ID: %w", err)
	}

	stateFile := s.stateFilePath(sessionID)

	data, err := os.ReadFile(stateFile) //nolint:gosec // stateFile is derived from sessionID
	if os.IsNotExist(err) {
		return nil, nil //nolint:nilnil // nil,nil indicates session not found (expected case)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read session state: %w", err)
	}

	var state State
	if err := json.Unmarshal(data, &state); err != nil {
		return nil, fmt.Errorf("failed to unmarshal session state: %w", err)
	}
	return &state, nil
}

// Save saves the session state atomically.
func (s *StateStore) Save(ctx context.Context, state *State) error {
	_ = ctx // Reserved for future use

	// Validate session ID to prevent path traversal
	if err := validation.ValidateSessionID(state.SessionID); err != nil {
		return fmt.Errorf("invalid session ID: %w", err)
	}

	if err := os.MkdirAll(s.stateDir, 0o750); err != nil {
		return fmt.Errorf("failed to create session state directory: %w", err)
	}

	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal session state: %w", err)
	}

	stateFile := s.stateFilePath(state.SessionID)

	// Atomic write: write to temp file, then rename
	tmpFile := stateFile + ".tmp"
	if err := os.WriteFile(tmpFile, data, 0o600); err != nil {
		return fmt.Errorf("failed to write session state: %w", err)
	}
	if err := os.Rename(tmpFile, stateFile); err != nil {
		return fmt.Errorf("failed to rename session state file: %w", err)
	}
	return nil
}

// Clear removes the session state file for the given session ID.
func (s *StateStore) Clear(ctx context.Context, sessionID string) error {
	_ = ctx // Reserved for future use

	// Validate session ID to prevent path traversal
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return fmt.Errorf("invalid session ID: %w", err)
	}

	stateFile := s.stateFilePath(sessionID)

	if err := os.Remove(stateFile); err != nil {
		if os.IsNotExist(err) {
			return nil // Already gone, not an error
		}
		return fmt.Errorf("failed to remove session state file: %w", err)
	}
	return nil
}

// RemoveAll removes the entire session state directory.
// This is used during uninstall to completely remove all session state.
func (s *StateStore) RemoveAll() error {
	if err := os.RemoveAll(s.stateDir); err != nil {
		return fmt.Errorf("failed to remove session state directory: %w", err)
	}
	return nil
}

// List returns all session states.
func (s *StateStore) List(ctx context.Context) ([]*State, error) {
	_ = ctx // Reserved for future use

	entries, err := os.ReadDir(s.stateDir)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read session state directory: %w", err)
	}

	var states []*State
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
			continue
		}
		if strings.HasSuffix(entry.Name(), ".tmp") {
			continue // Skip temp files
		}

		sessionID := strings.TrimSuffix(entry.Name(), ".json")
		state, err := s.Load(ctx, sessionID)
		if err != nil {
			continue // Skip corrupted state files
		}
		if state == nil {
			continue
		}

		states = append(states, state)
	}
	return states, nil
}

// FindByBaseCommit finds all sessions based on the given commit hash.
func (s *StateStore) FindByBaseCommit(ctx context.Context, baseCommit string) ([]*State, error) {
	allStates, err := s.List(ctx)
	if err != nil {
		return nil, err
	}

	var matching []*State
	for _, state := range allStates {
		if state.BaseCommit == baseCommit {
			matching = append(matching, state)
		}
	}
	return matching, nil
}

// FindByWorktree finds all sessions for the given worktree path.
func (s *StateStore) FindByWorktree(ctx context.Context, worktreePath string) ([]*State, error) {
	allStates, err := s.List(ctx)
	if err != nil {
		return nil, err
	}

	var matching []*State
	for _, state := range allStates {
		if state.WorktreePath == worktreePath {
			matching = append(matching, state)
		}
	}
	return matching, nil
}

// stateFilePath returns the path to a session state file.
func (s *StateStore) stateFilePath(sessionID string) string {
	return filepath.Join(s.stateDir, sessionID+".json")
}

// getGitCommonDir returns the path to the shared git directory.
// In a regular checkout, this is .git/
// In a worktree, this is the main repo's .git/ (not .git/worktrees/<name>/)
func getGitCommonDir() (string, error) {
	ctx := context.Background()
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
	cmd.Dir = "."
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get git common dir: %w", err)
	}

	commonDir := strings.TrimSpace(string(output))

	// git rev-parse --git-common-dir returns relative paths from the working directory,
	// so we need to make it absolute if it isn't already
	if !filepath.IsAbs(commonDir) {
		commonDir = filepath.Join(".", commonDir)
	}

	return filepath.Clean(commonDir), nil
}

// GetWorktreePath returns the absolute path to the current worktree root.
func GetWorktreePath() (string, error) {
	ctx := context.Background()
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get worktree path: %w", err)
	}
	return strings.TrimSpace(string(output)), nil
}

// GetOrCreateEntireSessionID returns a stable session ID for the given agent session ID.
// If a session state already exists with this ID, returns that session ID
// (preserving the original date prefix). Otherwise creates a new ID with today's date.
//
// When multiple state files exist for the same ID (due to the midnight-crossing bug),
// this function picks the most recent by date and cleans up older duplicates.
//
// This function never returns an error - it always falls back to generating a new ID
// if any issues occur (e.g., corrupt git repo, permission problems, invalid ID).
//
// Note: This function is not thread-safe. Concurrent calls with the same ID may
// race on file cleanup. In practice this is not an issue since agent hooks are
// called sequentially within a session.
func GetOrCreateEntireSessionID(agentSessionID string) string {
	// Validate ID format to prevent path traversal attacks
	if err := validation.ValidateAgentSessionID(agentSessionID); err != nil {
		logging.Warn(context.Background(), "invalid agent session ID",
			slog.String("input", agentSessionID),
			slog.Any("error", err))
		// Invalid ID - return it anyway (will fail downstream with clearer error)
		// Don't generate random ID as that breaks session continuity
		return sessionid.EntireSessionID(agentSessionID)
	}

	commonDir, err := getGitCommonDir()
	if err != nil {
		// Can't get common dir (corrupt git repo?) - fall back to new ID
		return sessionid.EntireSessionID(agentSessionID)
	}

	stateDir := filepath.Join(commonDir, sessionStateDirName)
	entries, err := os.ReadDir(stateDir)
	if err != nil {
		// State dir doesn't exist or can't read it - fall back to new ID
		return sessionid.EntireSessionID(agentSessionID)
	}

	// Collect all matching session IDs
	var matches []string
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
			continue
		}

		existingSessionID := strings.TrimSuffix(entry.Name(), ".json")
		existingUUID := sessionid.ModelSessionID(existingSessionID)

		if existingUUID == agentSessionID {
			matches = append(matches, existingSessionID)
		}
	}

	if len(matches) == 0 {
		// No existing session found - create new ID with today's date
		return sessionid.EntireSessionID(agentSessionID)
	}

	// Pick most recent (YYYY-MM-DD sorts correctly lexicographically)
	sort.Strings(matches)
	mostRecent := matches[len(matches)-1]

	// Best-effort cleanup of old duplicates (ignore errors)
	for _, oldID := range matches[:len(matches)-1] {
		oldFile := filepath.Join(stateDir, oldID+".json")
		_ = os.Remove(oldFile)
	}

	return mostRecent
}

