   412→// preTaskStateFile returns the absolute path to the pre-task state file for a tool use.
   413→// Works correctly from any subdirectory within the repository.
   414→func preTaskStateFile(toolUseID string) string {
   415→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
   416→	if err != nil {
   417→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
   418→	}
   419→	return filepath.Join(tmpDirAbs, fmt.Sprintf("pre-task-%s.json", toolUseID))
   420→}
   421→
   422→// preTaskFilePrefix is the prefix for pre-task state files
   423→const preTaskFilePrefix = "pre-task-"
   424→
   425→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
   426→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
   427→// When multiple pre-task files exist (nested subagents), returns the most recently
   428→// modified one.
   429→// Works correctly from any subdirectory within the repository.
   430→func FindActivePreTaskFile() (taskToolUseID string, found bool) {
   431→	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
   432→	if err != nil {
   433→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
   434→	}
   435→	entries, err := os.ReadDir(tmpDirAbs)
   436→	if err != nil {
   437→		return "", false
   438→	}
   439→
   440→	var latestFile string
   441→	var latestTime time.Time
   442→
   443→	for _, entry := range entries {
   444→		if entry.IsDir() {
   445→			continue
   446→		}
   447→		name := entry.Name()
   448→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
   449→			continue
   450→		}
   451→
   452→		// Check modification time for nested subagent handling
   453→		info, err := entry.Info()
   454→		if err != nil {
   455→			continue
   456→		}
   457→		if latestFile == "" || info.ModTime().After(latestTime) {
   458→			latestFile = name
   459→			latestTime = info.ModTime()
   460→		}
   461→	}
   462→
   463→	if latestFile == "" {
   464→		return "", false
   465→	}
   466→
   467→	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
   468→	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
   469→	toolUseID = strings.TrimSuffix(toolUseID, ".json")
   470→	return toolUseID, true
   471→}
   472→
   473→// DetectChangedFiles detects files that have been modified, added, or deleted
   474→// since the last commit (or compared to the index for incremental checkpoints).
   475→// Returns three slices: modified files, new (untracked) files, and deleted files.
   476→// Excludes .entire/ directory from all results.
   477→func DetectChangedFiles() (modified, newFiles, deleted []string, err error) {
   478→	repo, err := openRepository()
   479→	if err != nil {
   480→		return nil, nil, nil, fmt.Errorf("failed to open repository: %w", err)
   481→	}
   482→
   483→	worktree, err := repo.Worktree()
   484→	if err != nil {
   485→		return nil, nil, nil, fmt.Errorf("failed to get worktree: %w", err)
   486→	}
   487→
   488→	status, err := worktree.Status()
   489→	if err != nil {
   490→		return nil, nil, nil, fmt.Errorf("failed to get status: %w", err)
   491→	}
   492→
   493→	for file, st := range status {
   494→		// Skip .entire directory
   495→		if paths.IsInfrastructurePath(file) {
   496→			continue
   497→		}
   498→
   499→		// Handle different status codes
   500→		// Worktree status indicates changes not yet staged
   501→		// Staging status indicates changes staged for commit
   502→		switch {
   503→		case st.Worktree == git.Untracked:
   504→			// New untracked file
   505→			newFiles = append(newFiles, file)
   506→		case st.Worktree == git.Deleted || st.Staging == git.Deleted:
   507→			// Deleted file
   508→			deleted = append(deleted, file)
   509→		case st.Worktree == git.Modified || st.Staging == git.Modified ||
   510→			st.Worktree == git.Added || st.Staging == git.Added:
   511→			// Modified or staged file
   512→			modified = append(modified, file)
   513→		}
   514→	}
   515→
   516→	return modified, newFiles, deleted, nil
   517→}
   518→
   519→// GetNextCheckpointSequence returns the next sequence number for incremental checkpoints.
   520→// It counts existing checkpoint files in the task metadata checkpoints directory.
   521→// Returns 1 if no checkpoints exist yet.
   522→func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
   523→	// ctx.SessionID is already an Entire session ID (date-prefixed), so use SessionMetadataDirFromEntireID
   524→	sessionMetadataDir := paths.SessionMetadataDirFromEntireID(sessionID)
   525→	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
   526→	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")
   527→
   528→	entries, err := os.ReadDir(checkpointsDir)
   529→	if err != nil {
   530→		// Directory doesn't exist or can't be read - start at 1
   531→		return 1
   532→	}
   533→
   534→	// Count JSON files (checkpoints)
   535→	count := 0
   536→	for _, entry := range entries {
   537→		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
   538→			count++
   539→		}
   540→	}
   541→
   542→	return count + 1
   543→}
