   210→}
   211→
   212→// ComputeDeletedFiles returns files that were deleted during the session
   213→// (tracked files that no longer exist).
   214→func ComputeDeletedFiles() ([]string, error) {
   215→	repo, err := openRepository()
   216→	if err != nil {
   217→		return nil, err
   218→	}
   219→
   220→	worktree, err := repo.Worktree()
   221→	if err != nil {
   222→		return nil, err
   223→	}
   224→
   225→	status, err := worktree.Status()
   226→	if err != nil {
   227→		return nil, err
   228→	}
   229→
   230→	var deletedFiles []string
   231→	for file, st := range status {
   232→		// Skip .entire directory
   233→		if paths.IsInfrastructurePath(file) {
   234→			continue
   235→		}
   236→
   237→		// Find deleted files that haven't been staged yet
   238→		if st.Worktree == git.Deleted && st.Staging != git.Deleted {
   239→			deletedFiles = append(deletedFiles, file)
   240→		}
   241→	}
   242→
   243→	return deletedFiles, nil
   244→}
   245→
   246→// FilterAndNormalizePaths converts absolute paths to relative and filters out
   247→// infrastructure paths and paths outside the repo.
   248→func FilterAndNormalizePaths(files []string, cwd string) []string {
   249→	var result []string
   250→	for _, file := range files {
   251→		relPath := paths.ToRelativePath(file, cwd)
   252→		if relPath == "" {
   253→			continue // outside repo
   254→		}
   255→		if paths.IsInfrastructurePath(relPath) {
   256→			continue // skip .entire directory
   257→		}
   258→		result = append(result, relPath)
   259→	}
   260→	return result
