   381→// extractModifiedFiles extracts the list of files modified by tool calls
   382→func extractModifiedFiles(transcript []transcriptLine) []string {
   383→	fileSet := make(map[string]bool)
   384→	var files []string
   385→
   386→	for _, line := range transcript {
   387→		if line.Type == transcriptTypeAssistant {
   388→			var msg assistantMessage
   389→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   390→				continue
   391→			}
   392→
   393→			for _, block := range msg.Content {
   394→				if block.Type == "tool_use" {
   395→					isModifyTool := false
   396→					for _, name := range claudecode.FileModificationTools {
   397→						if block.Name == name {
   398→							isModifyTool = true
   399→							break
   400→						}
   401→					}
   402→
   403→					if isModifyTool {
   404→						var input toolInput
   405→						if err := json.Unmarshal(block.Input, &input); err != nil {
   406→							continue
   407→						}
   408→
   409→						file := input.FilePath
   410→						if file == "" {
   411→							file = input.NotebookPath
   412→						}
   413→
   414→						if file != "" && !fileSet[file] {
   415→							fileSet[file] = true
   416→							files = append(files, file)
   417→						}
   418→					}
   419→				}
   420→			}
   421→		}
   422→	}
   423→
   424→	return files
   425→}
   426→
   427→// extractKeyActions extracts key actions from the transcript for context file
   428→func extractKeyActions(transcript []transcriptLine, maxActions int) []string {
   429→	var keyActions []string
   430→
   431→	for _, line := range transcript {
   432→		if line.Type == transcriptTypeAssistant {
   433→			var msg assistantMessage
   434→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   435→				continue
   436→			}
   437→
   438→			for _, block := range msg.Content {
   439→				if block.Type == "tool_use" {
   440→					var input toolInput
   441→					_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing for display purposes
   442→
   443→					detail := input.Description
   444→					if detail == "" {
   445→						detail = input.Command
   446→					}
   447→					if detail == "" {
   448→						detail = input.FilePath
   449→					}
   450→					if detail == "" {
   451→						detail = input.Pattern
   452→					}
   453→
   454→					action := "- **" + block.Name + "**: " + detail
   455→					keyActions = append(keyActions, action)
   456→					if len(keyActions) >= maxActions {
   457→						return keyActions
   458→					}
   459→				}
   460→			}
   461→		}
   462→	}
   463→
   464→	return keyActions
   465→}
   466→
   467→// AgentTranscriptPath returns the path to a subagent's transcript file.
   468→// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
   469→// as the main transcript.
   470→func AgentTranscriptPath(transcriptDir, agentID string) string {
   471→	return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
   472→}
   473→
   474→// toolResultBlock represents a tool_result in a user message
   475→type toolResultBlock struct {
   476→	Type      string `json:"type"`
   477→	ToolUseID string `json:"tool_use_id"`
   478→}
   479→
   480→// userMessageWithToolResults represents a user message that may contain tool results
   481→type userMessageWithToolResults struct {
   482→	Content []toolResultBlock `json:"content"`
   483→}
   484→
   485→// FindCheckpointUUID finds the UUID of the message containing the tool_result
   486→// for the given tool_use_id. This is used to find the checkpoint point for
   487→// transcript truncation when rewinding to a task.
   488→// Returns the UUID and true if found, empty string and false otherwise.
   489→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
   490→	for _, line := range transcript {
   491→		if line.Type != transcriptTypeUser {
   492→			continue
   493→		}
   494→
   495→		var msg userMessageWithToolResults
   496→		if err := json.Unmarshal(line.Message, &msg); err != nil {
   497→			continue
   498→		}
   499→
   500→		for _, block := range msg.Content {
