	// === CHECKPOINT 2: Agent makes more changes ===
	checkpoint2Content := testCheckpoint1Content + "\nfunc agentFunc2() {\n\tprintln(\"agent2\")\n}\n"
	if err := os.WriteFile(testFile, []byte(checkpoint2Content), 0o644); err != nil {
