	}
	if state.CheckpointCount != 0 {
		t.Errorf("CheckpointCount = %d, want 0", state.CheckpointCount)
	}
	if state.CondensedTranscriptLines != 0 {
		t.Errorf("CondensedTranscriptLines = %d, want 0", state.CondensedTranscriptLines)
	}
}

